window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[279]={"id":"279","numero":279,"titre":"Cirrhose","objectifs":[{"id":"279-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la cirrhose","contenu":"<table>\n        <tbody>\n          <tr>\n            <th>Définition HISTOLOGIQUE ⭐</th>\n            <td><span class=\"kw-bio\">Fibrose cicatricielle diffuse</span> qui est :\n              <ul>\n                <li><strong>Mutilante</strong> : <span class=\"kw-alerte\">détruit l'architecture lobulaire normale du foie</span></li>\n                <li><strong>Annulaire</strong> : délimitant des nodules hépatocytaires de structure anormale « <span class=\"kw-def\">nodules de régénération</span> »</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <th>2 types</th>\n            <td>Il existe aussi des cirrhoses mixtes (micro-/macronodulaires)\n              <ul>\n                <li>Cirrhoses <span class=\"kw-alerte\">micronodulaires</span> : majorité des nodules cirrhotiques sont <span class=\"kw-chiffre\">&lt; 3 mm</span></li>\n                <li>Cirrhoses <span class=\"kw-alerte\">macronodulaires</span> ⭐ : majorité des nodules cirrhotiques sont <span class=\"kw-chiffre\">&gt; 3 mm</span>\n                  <ul><li>(<span class=\"kw-alerte\">diagnostic plus difficile quelle que soit la technique</span>, car moins de tissu fibreux en excès)</li></ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <th>Physiopath.</th>\n            <td>\n              <ol>\n                <li><strong>Toutes les maladies chroniques du foie</strong> peuvent aboutir à une cirrhose si évolution prolongée : après <span class=\"kw-chiffre\">10–20 ans d'évolution</span> en général</li>\n                <li>Réparation comportera une <span class=\"kw-def\">régénération hépatocytaire</span>, mais aussi possiblement une cicatrisation (= remplacement du tissu détruit par de la fibrose)</li>\n                <li>Fibrose va au bout d'un certain temps devenir mutilante c'est-à-dire modifier l'architecture du tissu</li>\n                <li>Aboutissement de ce processus permanent de « destruction/réparation avec fibrose » est la cirrhose</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <th>Épidémio.</th>\n            <td>\n              <ul>\n                <li>Prévalence : <span class=\"kw-chiffre\">0,2 – 0,3 %</span> (500 000 personnes sont atteintes de fibrose hépatique avancé : F3 et cirrhose)</li>\n                <li>Incidence : <span class=\"kw-chiffre\">150-200 cas/an</span></li>\n                <li>Mortalité : <span class=\"kw-alerte\">16.000 décès/an</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <th>Cirrhose compensée</th>\n            <td>Stade précoce/compensé est <strong>asymptomatique</strong> ⭐\n              <ul><li>(Il peut exister dans certains cas des signes cliniques/biologiques/morphologiques de cirrhose)</li></ul>\n            </td>\n          </tr>\n          <tr>\n            <th>Cirrhose décompensée<br>(complications)</th>\n            <td>\n              <ul>\n                <li><strong>Insuffisance hépatique</strong> : <span class=\"kw-alerte\">Ascite</span>, <span class=\"kw-alerte\">Ictère</span>, <span class=\"kw-alerte\">Encéphalopathie hépatique</span>, <span class=\"kw-alerte\">Syndrome hépatorénal</span></li>\n                <li><strong>Hypertension portale</strong> (fibrose gêne le flux sanguin portal) : <span class=\"kw-alerte\">Hémorragies digestives</span> (rupture de varices œsophagiennes et/ou gastriques)</li>\n                <li><strong>Infections bactériennes</strong> : représentent <span class=\"kw-chiffre\">25 %</span> des décès des cirrhotiques, incluant <span class=\"kw-alerte\">infection à pneumocoque ++</span>, et <span class=\"kw-alerte\">infection du liquide d'ascite</span></li>\n                <li><strong>Carcinome hépatocellulaire, Cholangiocarcinome</strong> : représente la <span class=\"kw-alerte\">1ère cause de mortalité du cirrhotique</span>\n                  <ul><li>(CHC peut survenir avant le stade cirrhose pour certaines pathologiques : VHB, hémochromatose, stéato-hépatite métabolique)</li></ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <th>Réversible ?</th>\n            <td><span class=\"kw-alerte\">Affection irréversible selon MIR</span> ⭐, Affection réversible selon asclepia</td>\n          </tr>\n        </tbody>\n      </table>","frequence":2},{"id":"279-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de la cirrhose hépatique","contenu":"<p>La <span class=\"kw-def\">cirrhose</span> est une pathologie <strong>fréquente</strong> et une cause importante de <span class=\"kw-def\">mortalité</span> en France.</p>\n      <table >\n        <thead><tr><th>Indicateur épidémiologique</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">0,2 à 0,3 %</span> — environ 500 000 personnes atteintes de <span class=\"kw-bio\">fibrose hépatique avancée</span> (<span class=\"kw-def\">F3</span> et <span class=\"kw-def\">cirrhose</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td><span class=\"kw-chiffre\">150 à 200 cas / an</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span></td><td><span class=\"kw-alerte\">16 000 décès / an</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"279-3","rang":"A","rubrique":"Définition","titre":"Connaître les stades évolutifs de la cirrhose","contenu":"<p>La <span class=\"kw-def\">cirrhose</span> évolue en <strong>deux grands stades</strong> : le passage de la <span class=\"kw-def\">cirrhose</span> compensée à la <span class=\"kw-def\">cirrhose</span> décompensée conditionne le <span class=\"kw-def\">pronostic</span>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/279/schema-physiopath-cirrhose.png\" alt=\"Schéma physiopathologique de la cirrhose : agent causal, inflammation/fibrose, cirrhose, évolutions HTP/IHC/CHC\">\n        <figcaption>Histoire naturelle de la <span class=\"kw-def\">cirrhose</span>. Un <strong>agent causal</strong> (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">NASH</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">hémochromatose</span>, maladies rares) entretient sur des décennies une <strong>inflammation</strong> puis une <strong>fibrose</strong> hépatiques chroniques aboutissant à la <strong><span class=\"kw-def\">cirrhose</span></strong>. Celle-ci se complique selon trois axes : <span class=\"kw-clinique\">hypertension</span> portale (hémorragie digestive), <span class=\"kw-ci\">insuffisance hépatique</span> (<span class=\"kw-clinique\">ascite</span>, <span class=\"kw-clinique\">ictère</span>, encéphalopathie, syndrome hépatorénal) et cancer primitif du foie (<span class=\"kw-chiffre\">1 à 5 %</span> / an).</figcaption>\n      </figure>\n      <h4 class=\"obj-h4\"><span class=\"kw-def\">Stade</span> 1 — <span class=\"kw-def\">Cirrhose</span> compensée</h4>\n      <ul>\n        <li><span class=\"kw-def\">Stade</span> précoce, le plus souvent <span class=\"kw-clinique\">asymptomatique</span></li>\n        <li>Il peut exister des signes cliniques, <span class=\"kw-bio\">biologiques</span> ou morphologiques discrets de <span class=\"kw-def\">cirrhose</span></li>\n        <li>Objectif thérapeutique : <strong>maintenir la compensation</strong> le plus longtemps possible</li>\n      </ul>\n      <h4 class=\"obj-h4\"><span class=\"kw-def\">Stade</span> 2 — <span class=\"kw-def\">Cirrhose</span> décompensée : <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>rands axes de complications</h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td>Insuffisance hépatocellulaire</td><td><span class=\"kw-clinique\">Ascite</span> ; <span class=\"kw-clinique\">ictère</span> ; <span class=\"kw-alerte\">encéphalopathie hépatique</span> ; <span class=\"kw-alerte\">syndrome hépatorénal</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hypertension</span> portale</td><td><span class=\"kw-alerte\">Hémorragies digestives</span> — <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-clinique\">varices œsophagiennes</span> et/ou gastriques (la fibrose gêne le flux sanguin portal)</td></tr>\n          <tr><td>Infections bactériennes</td><td>Représentent <span class=\"kw-chiffre\">25 %</span> des décès des cirrhotiques — dont l'infection à <span class=\"kw-etio\">pneumocoque</span> et l'<span class=\"kw-alerte\">infection du liquide d'<span class=\"kw-clinique\">ascite</span></span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Carcinome</span> hépatocellulaire (± cholangiocarcinome)</td><td><span class=\"kw-alerte\">1ʳᵉ cause de mortalité</span> du cirrhotique ; le CHC peut survenir <strong>avant</strong> le <span class=\"kw-def\">stade</span> de <span class=\"kw-def\">cirrhose</span> pour certaines causes (<span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">hémochromatose</span>, stéatohépatite métabolique)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Définir la <span class=\"kw-alerte\">décompensation</span>.</strong> La <span class=\"kw-def\">cirrhose</span> est dite décompensée dès la survenue d'<strong>une seule</strong> de ces complications. Toutes sont associées à une <span class=\"kw-alerte\">mortalité élevée</span>.\n      </div>","frequence":3},{"id":"279-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques de cirrhose","contenu":"<p>L'examen clinique d'un patient cirrhotique <strong>peut être strictement normal</strong>. Lorsqu'ils sont présents, <span class=\"kw-clinique\">les</span> signes se répartissent entre la <span class=\"kw-clinique\">palpation du foie</span>, les <span class=\"kw-def\">signes d'hypertension portale (HTP)</span> et les <span class=\"kw-def\">signes d'insuffisance hépatocellulaire (IHC)</span>.</p>\n      <figure class=\"obj-figure cir-bodymap\" role=\"group\" aria-label=\"Carte corporelle des signes cliniques de la cirrhose : signes d'insuffisance hépatocellulaire (ictère conjonctival, foetor hepaticus, angiomes stellaires, gynécomastie, érythrose palmaire, hippocratisme digital et leuconychie, astérixis, atrophie des organes génitaux externes), signes d'hypertension portale (circulation veineuse collatérale péri-ombilicale, ascite, splénomégalie) et signe de palpation (hépatomégalie dure à bord tranchant).\">\n        <div class=\"cir-bodymap__row\">\n          <div class=\"cir-legend-group cir-legend-group--left\">\n            <h5>Insuffisance hépatocellulaire</h5>\n            <ul>\n              <li><span class=\"cir-num cir-num--ihc\">1</span> <span><span class=\"kw-clinique\">Ictère</span> conjonctival — tardif, mauvais <span class=\"kw-def\">pronostic</span></span></li>\n              <li><span class=\"cir-num cir-num--ihc\">2</span> <span><span class=\"kw-clinique\">Foetor hepaticus</span></span></li>\n              <li><span class=\"cir-num cir-num--ihc\">3</span> <span><span class=\"kw-clinique\">Angiomes stellaires</span> du territoire cave sup. (<span class=\"kw-chiffre\">≥ 5</span>)</span></li>\n              <li><span class=\"cir-num cir-num--ihc\">4</span> <span><span class=\"kw-clinique\">Gynécomastie</span> · dépilation</span></li>\n              <li><span class=\"cir-num cir-num--ihc\">5</span> <span><span class=\"kw-clinique\">Érythrose</span> palmaire et plantaire</span></li>\n              <li><span class=\"cir-num cir-num--ihc\">6</span> <span><span class=\"kw-clinique\">Hippocratisme digital</span> · <span class=\"kw-clinique\">leuconychie</span></span></li>\n              <li><span class=\"cir-num cir-num--ihc\">7</span> <span><span class=\"kw-clinique\">Astérixis</span> (encéphalopathie)</span></li>\n              <li><span class=\"cir-num cir-num--ihc\">8</span> <span><span class=\"kw-clinique\">Atrophie des OGE</span> ♂ · <span class=\"kw-clinique\">aménorrhée</span> ♀</span></li>\n            </ul>\n          </div>\n          <svg viewBox=\"0 0 380 400\" role=\"img\" aria-hidden=\"true\">\n          <!-- silhouette -->\n          <path d=\"M173 260 L168 392\" stroke=\"var(--accent-dash)\" stroke-width=\"30\" fill=\"none\" stroke-linecap=\"round\"/>\n          <path d=\"M207 260 L212 392\" stroke=\"var(--accent-dash)\" stroke-width=\"30\" fill=\"none\" stroke-linecap=\"round\"/>\n          <path d=\"M158 112 L120 238\" stroke=\"var(--accent-dash)\" stroke-width=\"22\" fill=\"none\" stroke-linecap=\"round\"/>\n          <path d=\"M222 112 L260 238\" stroke=\"var(--accent-dash)\" stroke-width=\"22\" fill=\"none\" stroke-linecap=\"round\"/>\n          <path d=\"M154 104 C146 135 143 166 152 190 C138 208 137 240 158 264 L222 264 C243 240 242 208 228 190 C237 166 234 135 226 104 Z\" fill=\"var(--accent-dash)\"/>\n          <rect x=\"178\" y=\"80\" width=\"24\" height=\"28\" rx=\"6\" fill=\"var(--accent-dash)\"/>\n          <circle cx=\"190\" cy=\"56\" r=\"30\" fill=\"var(--accent-dash)\"/>\n          <circle cx=\"118\" cy=\"240\" r=\"13\" fill=\"var(--accent-dash)\"/>\n          <circle cx=\"262\" cy=\"240\" r=\"13\" fill=\"var(--accent-dash)\"/>\n          <!-- marqueurs IHC -->\n          <g><circle cx=\"180\" cy=\"52\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"180\" y=\"55.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">1</text></g>\n          <g><circle cx=\"201\" cy=\"66\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"201\" y=\"69.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">2</text></g>\n          <g><circle cx=\"190\" cy=\"124\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"190\" y=\"127.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">3</text></g>\n          <g><circle cx=\"165\" cy=\"142\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"165\" y=\"145.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">4</text></g>\n          <g><circle cx=\"118\" cy=\"240\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"118\" y=\"243.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">5</text></g>\n          <g><circle cx=\"262\" cy=\"240\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"262\" y=\"243.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">6</text></g>\n          <g><circle cx=\"250\" cy=\"206\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"250\" y=\"209.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">7</text></g>\n          <g><circle cx=\"188\" cy=\"254\" r=\"8.5\" fill=\"var(--spe-hepato)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"188\" y=\"257.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">8</text></g>\n          <!-- marqueurs HTP -->\n          <g><circle cx=\"184\" cy=\"205\" r=\"8.5\" fill=\"var(--spe-cardio)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"184\" y=\"208.5\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\" fill=\"#fff\">9</text></g>\n          <g><circle cx=\"206\" cy=\"232\" r=\"8.5\" fill=\"var(--spe-cardio)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"206\" y=\"235.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">10</text></g>\n          <g><circle cx=\"232\" cy=\"196\" r=\"8.5\" fill=\"var(--spe-cardio)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"232\" y=\"199.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">11</text></g>\n          <!-- marqueur palpation -->\n          <g><circle cx=\"150\" cy=\"186\" r=\"8.5\" fill=\"var(--ink-muted)\" stroke=\"var(--bg-card)\" stroke-width=\"1.6\"/><text x=\"150\" y=\"189.5\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">12</text></g>\n          </svg>\n          <div class=\"cir-legend-group cir-legend-group--right\">\n            <h5><span class=\"kw-clinique\">Hypertension</span> portale</h5>\n            <ul>\n              <li><span class=\"cir-num cir-num--htp\">9</span> <span><span class=\"kw-clinique\">Circulation veineuse collatérale</span> péri-ombilicale</span></li>\n              <li><span class=\"cir-num cir-num--htp\">10</span> <span><span class=\"kw-clinique\">Ascite</span> (distension abdominale)</span></li>\n              <li><span class=\"cir-num cir-num--htp\">11</span> <span><span class=\"kw-clinique\">Splénomégalie</span></span></li>\n            </ul>\n            <h5 style=\"margin-top:12px\">Palpation du foie</h5>\n            <ul>\n              <li><span class=\"cir-num cir-num--palp\">12</span> <span>Foie <span class=\"kw-clinique\">dur</span>, <span class=\"kw-clinique\">bord inférieur tranchant</span> (taille variable)</span></li>\n            </ul>\n          </div>\n        </div>\n        <figcaption><span class=\"kw-clinique\">Les</span> signes cliniques de la <span class=\"kw-def\">cirrhose</span>, regroupés par mécanisme : <strong><span class=\"kw-alerte\">insuffisance hépatocellulaire</span></strong> (terracotta), <strong><span class=\"kw-clinique\">hypertension</span> portale</strong> (bleu) et <strong>palpation hépatique</strong> (gris). Tous peuvent manquer au <span class=\"kw-def\">stade</span> compensé.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Origine</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td>Palpation du foie</td><td>Foie de <strong>taille variable</strong> (normale, augmentée ou atrophique) ; s'il est palpable, il est souvent <span class=\"kw-clinique\">dur</span>, avec un <span class=\"kw-clinique\">bord inférieur tranchant</span></td></tr>\n          <tr><td>Signes d'<span class=\"kw-clinique\">HTP</span></td><td><span class=\"kw-clinique\">Splénomégalie</span> ; <span class=\"kw-clinique\">ascite</span> ; <span class=\"kw-clinique\">circulation veineuse collatérale</span> ép<span class=\"kw-chiffre\">iga</span>strique puis péri-ombilicale</td></tr>\n          <tr><td>Signes d'<span class=\"kw-bio\">IHC</span></td><td><strong><span class=\"kw-alerte\">Encéphalopathie hépatique</span> :</strong> <span class=\"kw-clinique\">astérixis</span>, <span class=\"kw-clinique\">inversion du cycle nycthéméral</span>, <span class=\"kw-clinique\">troubles cognitifs mineurs</span>, <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">troubles de la conscience</span><br><strong><span class=\"kw-clinique\">Ictère</span></strong> conjonctival ou cutané — tardif, de <span class=\"kw-alerte\">mauvais pronostic</span><br><strong><span class=\"kw-clinique\">Foetor hepaticus</span></strong> — odeur d'haleine caractéristique<br><strong><span class=\"kw-clinique\">Angiomes stellaires</span></strong> du territoire cave supérieur (visage, thorax, membres supérieurs), <span class=\"kw-chiffre\">significatifs si ≥ 5</span> — tache rouge étoilée disparaissant à la vitropression<br><strong><span class=\"kw-clinique\">Érythrose</span></strong> palmaire et plantaire<br><strong><span class=\"kw-clinique\">Hippocratisme digital</span></strong>, <span class=\"kw-clinique\">ongles blancs (leuconychie)</span>, agrandissement de la lunule<br><strong><span class=\"kw-clinique\">Hypogonadisme</span> :</strong> homme — <span class=\"kw-clinique\">atrophie des organes génitaux externes</span>, <span class=\"kw-clinique\">gynécomastie</span>, <span class=\"kw-clinique\">dépilation</span> ; femme — <span class=\"kw-clinique\">spanioménorrhée ou aménorrhée</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> L'examen clinique <span class=\"kw-alerte\">peut être normal</span> au <span class=\"kw-def\">stade</span> de <span class=\"kw-def\">cirrhose</span> compensée — sa normalité n'élimine en rien le diagnostic.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 278 — <span class=\"kw-clinique\">Ictère</span></em></p>","frequence":4},{"id":"279-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes paracliniques (biologiques et échographiques) associés à la cirrhose","contenu":"<p>Le diagnostic paraclinique repose sur la <span class=\"kw-bio\">biologie</span> et l'<span class=\"kw-imagerie\">échographie abdominale</span>. Le bilan <span class=\"kw-ttt\">biologique</span> peut être <strong>normal</strong>, surtout au <span class=\"kw-def\">stade</span> compensé.</p>\n      <h4 class=\"obj-h4\">Signes biologiques</h4>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Anomalies biologiques</th></tr></thead>\n        <tbody>\n          <tr><td>Cytolyse hépatique</td><td>Élévation <strong>modérée</strong> des <span class=\"kw-bio\">transaminases</span> et de la <span class=\"kw-bio\">γ-GT</span></td></tr>\n          <tr><td>Insuffisance hépatocellulaire</td><td><strong>Baisse des facteurs de coagulation :</strong> <span class=\"kw-bio\">facteur VII</span> en 1ᵉʳ (<span class=\"kw-bio\">TP</span>) ; puis <span class=\"kw-bio\">facteurs II et X</span> ; puis <span class=\"kw-bio\">facteur V</span> — facteur de gravité<br><span class=\"kw-bio\">Hypoalbuminémie</span> ; <span class=\"kw-bio\">hyperbilirubinémie</span> conjuguée ou mixte ; <span class=\"kw-bio\">élévation de l'INR</span> ; <span class=\"kw-bio\">hypofibrinogénémie</span> dans <span class=\"kw-clinique\">les</span> formes sévères<br><span class=\"kw-bio\">Temps de lyse des euglobulines (Von Kaulla)</span> raccourci <span class=\"kw-chiffre\">&lt; 1 h</span> — témoin d'hyperfibrinolyse</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hypertension</span> portale (hypersplénisme)</td><td>Cytopénies de séquestration : <span class=\"kw-bio\">thrombopénie</span> &gt; leucopénie &gt; anémie</td></tr>\n          <tr><td>Anémie — origine multifactorielle</td><td>Au-delà de l'hypersplénisme : <span class=\"kw-bio\">carence martiale</span> (saignement digestif chronique) ; <span class=\"kw-bio\">carence en folates</span> ; <span class=\"kw-bio\">hémolyse</span> par anomalie corpusculaire <span class=\"kw-etio\">acquise</span> (acanthocytose)</td></tr>\n          <tr><td>Arguments « consommateur d'<span class=\"kw-etio\">alcool</span> »</td><td><span class=\"kw-bio\">Macrocytose</span> ; rapport <span class=\"kw-bio\">ASAT / ALAT ≥ 2</span> ; <span class=\"kw-bio\">bloc β-γ</span> à l'électrophorèse (hypergammaglobulinémie)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège du <span class=\"kw-bio\">bilan martial</span>.</strong> Une <span class=\"kw-bio\">hyperferritinémie</span> est possible dans toute maladie hépatique active : elle <span class=\"kw-alerte\">ne traduit pas forcément une hémochromatose</span> associée. De même, le <span class=\"kw-bio\">coefficient de saturation de la transferrine (CST)</span> peut être élevé en <span class=\"kw-def\">cirrhose</span> par <strong>baisse de synthèse hépatique de la <span class=\"kw-bio\">transferrine</span></strong> : un <span class=\"kw-alerte\">CST élevé n'équivaut donc pas à une surcharge en fer</span>.\n      </div>\n      <h4 class=\"obj-h4\">Signes échographiques</h4>\n      <table >\n        <thead><tr><th>Cible</th><th>Signes au <span class=\"kw-imagerie\">doppler</span> / <span class=\"kw-imagerie\">échographie</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cirrhose</span></td><td><span class=\"kw-radio\">Contours du foie irréguliers, bosselés</span> ; <span class=\"kw-radio\">dysmorphie</span> — atrophie (souvent du lobe droit) et hypertrophie (souvent du lobe gauche) ; <span class=\"kw-radio\">échostructure granitée</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hypertension</span> portale</td><td>Augmentation du <span class=\"kw-clinique\">diamètre</span> de la veine porte ; <span class=\"kw-clinique\">ascite</span> ; <span class=\"kw-clinique\">splénomégalie</span> ; voies de dérivation porto-caves ; au <span class=\"kw-imagerie\">doppler</span>, ralentissement ou <span class=\"kw-radio\">inversion du flux porte (flux hépatofuge)</span> si <span class=\"kw-clinique\">HTP</span> sévère</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 219 — Pathologie du fer</em></p>","frequence":3},{"id":"279-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les méthodes diagnostiques d’une cirrhose compensée","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif très tombé à l'EDN.</strong> <span class=\"kw-clinique\">Les</span> tests non invasifs de fibrose, leurs seuils, et les performances de la <span class=\"kw-imagerie\">PBH</span> sont des classiques d'annales.\n      </div>\n      <p>Devant une <strong>suspicion de <span class=\"kw-def\">cirrhose</span> compensée</strong>, le diagnostic repose en <span class=\"kw-def\">1ʳᵉ intention</span> sur des <strong>tests non invasifs</strong>. La <span class=\"kw-bio\">ponction-biopsie hépatique (PBH)</span> reste l'examen de référence mais <strong>n'est pas indispensable</strong>.</p>\n      <h4 class=\"obj-h4\">Tests non invasifs — 1ʳᵉ intention</h4>\n      <figure class=\"obj-figure cir-regle\" role=\"img\" aria-label=\"Réglette d'interprétation de l'élastométrie impulsionnelle (Fibroscan) en kilopascals : en dessous de 7 kPa la cirrhose est quasiment écartée, entre 7 et 12,5 kPa la zone est indéterminée, au-dessus de 12,5 kPa la cirrhose est fortement suspectée. La valeur normale est d'environ 5 kPa.\">\n        <div class=\"cir-regle__bar\">\n          <div class=\"cir-regle__seg seg--ok\">&lt; 7 kPa<br>cirrhose écartée</div>\n          <div class=\"cir-regle__seg seg--gris\">7 – 12,5<br>zone grise</div>\n          <div class=\"cir-regle__seg seg--susp\">&gt; 12,5 kPa<br>cirrhose fortement suspectée</div>\n        </div>\n        <div class=\"cir-regle__ticks\">\n          <span class=\"cir-regle__tick tick--5\">5 ≈ normale</span>\n          <span class=\"cir-regle__tick tick--7\">7</span>\n          <span class=\"cir-regle__tick tick--125\">12,5</span>\n        </div>\n        <figcaption>Dureté hépatique mesurée à jeun (<span class=\"kw-chiffre\">≥ 2 h</span>). <span class=\"kw-clinique\">Les</span> deux seuils <span class=\"kw-chiffre\">7</span> et <span class=\"kw-chiffre\">12,5 kPa</span> bornent la zone d'incertitude.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Test</th><th>Principe et interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Élastométrie</span> impulsionnelle (Fibroscan)</td><td>Mesure la <strong>dureté du foie</strong> en kPa via une onde de cisaillement<br><span class=\"kw-def\">Cirrhose</span> <strong>fortement suspectée</strong> si <span class=\"kw-chiffre\">&gt; 12,5 kPa</span> ; <span class=\"kw-def\">cirrhose</span> quasiment <strong>écartée</strong> si <span class=\"kw-chiffre\">&lt; 7 kPa</span> (normale ≈ 5 kPa)<br>Précaution : mesure réalisée <span class=\"kw-chiffre\">à jeun depuis ≥ 2 h</span></td></tr>\n          <tr><td>Biomarqueurs sériques de fibrose</td><td><strong>Test simple :</strong> <span class=\"kw-bio\">Fib-4</span><br><strong>Tests spécialisés :</strong> <span class=\"kw-bio\">FibroTest</span> ; <span class=\"kw-bio\">FibroMètre</span> ; <span class=\"kw-bio\">Hépascore</span><br>Limite : <span class=\"kw-alerte\">non validés pour toutes les maladies chroniques du foie</span> (ex. <span class=\"kw-etio\">hémochromatose</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\"><span class=\"kw-ttt\">Ponction</span>-<span class=\"kw-bio\">biopsie</span> hépatique — référence, en dernier recours</h4>\n      <ul>\n        <li><strong>Aspect :</strong> bandes de fibrose d'épaisseur variable, formant des nodules avec destruction de l'architecture lobulaire</li>\n        <li><strong><span class=\"kw-bio\">Spécificité 99 %</span></strong> — quasiment aucun faux positif</li>\n        <li><strong><span class=\"kw-bio\">Sensibilité 80 %</span></strong> — <span class=\"kw-clinique\">les</span> faux négatifs sont liés à une <span class=\"kw-bio\">biopsie</span> trop petite ou trop fragmentée, ou à une <span class=\"kw-alerte\">cirrhose macronodulaire</span> (nodules non visualisés sur une <span class=\"kw-bio\">biopsie</span> de <span class=\"kw-chiffre\">1 mm</span> de large)</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège d'annale.</strong> Le piège classique <span class=\"kw-alerte\">inverse faux positifs et faux négatifs</span> de la <span class=\"kw-imagerie\">PBH</span> : retenir une <strong>spécificité élevée (<span class=\"kw-chiffre\">99 %</span>)</strong> et une sensibilité moindre (<span class=\"kw-chiffre\">80 %</span>).\n      </div>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/ascites","label":"Radiopaedia : Ascites"},{"href":"https://radiopaedia.org/articles/cirrhosis","label":"Radiopaedia : Cirrhosis"},{"href":"https://radiopaedia.org/articles/oesophageal-varix","label":"Radiopaedia : Oesophageal varix"}]},{"id":"279-7","rang":"B","rubrique":"Etiologie","titre":"Connaître les étiologies de cirrhose et les arguments diagnostiques étiologiques","contenu":"<div class=\"callout callout-info\">\n        <strong>Objectif très tombé à l'EDN.</strong> Par ordre de fréquence : 1 — consommation excessive et prolongée d'<span class=\"kw-etio\">alcool</span> ; 2 — <span class=\"kw-etio\">NASH</span> (stéatohépatite métabolique) ; 3 — hépatites virales chroniques B et C.\n      </div>\n      <h4 class=\"obj-h4\">Causes fréquentes (5)</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Arguments diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td>Consommation excessive d'<span class=\"kw-etio\">alcool</span></td><td>Rapport <span class=\"kw-bio\">ASAT / ALAT ≥ 2</span> ; élévation de la <span class=\"kw-bio\">γ-GT</span> ; <span class=\"kw-etio\">hépatite</span> alcoolique en <span class=\"kw-bio\">histologie</span></td></tr>\n          <tr><td>Stéatopathie métabolique (<span class=\"kw-etio\">NASH</span>)</td><td><span class=\"kw-clinique\">Surcharge pondérale</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-def\">syndrome métabolique</span> ; données histologiques</td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> chronique B</td><td><span class=\"kw-bio\">AgHBs</span> ; <span class=\"kw-bio\">ADN VHB</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> chronique C</td><td><span class=\"kw-bio\">Anticorps anti-VHC</span> ; <span class=\"kw-bio\">ARN VHC</span> par <span class=\"kw-bio\">PCR</span> dans le sérum</td></tr>\n          <tr><td><span class=\"kw-etio\">Hémochromatose</span> <span class=\"kw-etio\">génétique</span></td><td><span class=\"kw-bio\">CST &gt; 45 %</span> ; <span class=\"kw-bio\">hyperferritinémie</span> ; <span class=\"kw-bio\">mutation homozygote C282Y du gène HFE</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\">Causes rares (6)</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Arguments diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> chronique B-delta</td><td>AgHBs ; <span class=\"kw-bio\">anticorps anti-VHD</span> ; ARN du virus D dans le sérum</td></tr>\n          <tr><td><span class=\"kw-etio\">Cholangite sclérosante primitive</span></td><td><span class=\"kw-etio\">MICI</span> associée ; cholangite diffuse en <span class=\"kw-imagerie\">bili-IRM</span> ou cholangiographie rétrograde</td></tr>\n          <tr><td>Cholangite biliaire primitive</td><td><span class=\"kw-bio\">Anticorps anti-mitochondries de type M2</span> ; femme d'âge mûr ; <span class=\"kw-clinique\">cholestase</span></td></tr>\n          <tr><td><span class=\"kw-def\">Cirrhose</span> biliaire secondaire</td><td>Antécédent d'<span class=\"kw-etio\">obstacle prolongé sur les voies biliaires</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> <span class=\"kw-etio\">auto-immune</span></td><td><span class=\"kw-bio\">Anticorps anti-tissus à titre élevé</span> (anti-muscle lisse, anti-LKM1) ; hypergammaglobulinémie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome de Budd</span>-Chiari</td><td><span class=\"kw-imagerie\">Obstruction des veines hépatiques</span> en imagerie ; affection prothrombotique</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\">Causes très rares</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Maladie de Wilson</span> :</strong> <span class=\"kw-bio\">céruloplasmine abaissée</span>, anneau de Kayser-Fleischer, cuprurie élevée, tests génétiques</li>\n        <li><strong>Déficit en α-1-antitrypsine :</strong> <span class=\"kw-bio\">α-1-antitrypsine effondrée</span>, anomalies pulmonaires associées</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Bilan étiologique systématique.</strong> En 1ʳᵉ intention : <span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">albumine</span>, bilan de coagulation, <span class=\"kw-bio\">ionogramme</span>-créatinine-<span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">sérologies VHB et VHC</span>, <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">bilan lipidique</span>, <span class=\"kw-bio\">ferritinémie et CST</span>, <span class=\"kw-bio\">électrophorèse des protéines</span>. En 2ⁿᵈ intention : <span class=\"kw-bio\">sérologie</span> delta si AgHBs positif, <span class=\"kw-bio\">AAN et anti-mitochondries M2</span>, anti-muscle lisse et anti-LKM1.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 167 — Hépatites virales · 219 — Pathologie du fer</em></p>","frequence":5},{"id":"279-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les quatre principales complications sévères de la cirrhose : hémorragie digestive ; encéphalopathie hépatique ; infection du liquide d’ascite ; syndrome hépato-rénal","contenu":"<div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — 4 complications à <span class=\"kw-def\">mortalité</span> élevée.</strong> <span class=\"kw-clinique\">Les</span> complications de la <span class=\"kw-def\">cirrhose</span> résultent de l'<strong><span class=\"kw-clinique\">hypertension</span> portale</strong>, de l'<strong><span class=\"kw-alerte\">insuffisance hépatocellulaire</span></strong> et/ou du <strong><span class=\"kw-clinique\">carcinome</span> hépatocellulaire</strong>. Elles sont <span class=\"kw-alerte\">intriquées</span> : chaque complication peut être due aux autres ou en induire une nouvelle — <strong>chaque complication doit donc faire rechercher systématiquement les autres</strong>.\n      </div>\n      <h4 class=\"obj-h4\"><span class=\"kw-clinique\">Les</span> 4 complications sévères</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Repères diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td>Hémorragie digestive</td><td>Liée à l'<span class=\"kw-clinique\">HTP</span> ; principal mécanisme = <span class=\"kw-alerte\">rupture de varices œsophagiennes</span><br><span class=\"kw-clinique\">Hématémèse</span>, <span class=\"kw-clinique\">méléna</span> ; <span class=\"kw-clinique\">tachycardie</span> = signe le plus précoce (sauf sous β-bloquant)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Encéphalopathie hépatique</span></td><td>Accumulation de toxiques non métabolisés — <span class=\"kw-bio\">hyperammoniémie</span> nécessaire au diagnostic<br><span class=\"kw-clinique\">Astérixis</span> (<span class=\"kw-clinique\">flapping</span> tremor) ; gradation en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>rades, du <span class=\"kw-def\">grade</span> 1 au <span class=\"kw-clinique\">coma</span> (<span class=\"kw-chiffre\">grade 4</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Infection du liquide d'<span class=\"kw-clinique\">ascite</span></span></td><td>= <span class=\"kw-clinique\">péritonite</span> <span class=\"kw-etio\">bactérienne</span> spontanée<br><span class=\"kw-def\">Diagnostic positif</span> : <span class=\"kw-chiffre\">PNN &gt; 250 / mm³</span> dans le liquide d'<span class=\"kw-clinique\">ascite</span> ; infection souvent <span class=\"kw-clinique\">asymptomatique</span><br><strong>Traitement :</strong> <span class=\"kw-ttt\">C3G (céfotaxime)</span> + <span class=\"kw-ttt\">albumine 20 %</span> à <span class=\"kw-chiffre\">J1 puis J3</span> ; <span class=\"kw-clinique\">ponction de contrôle à 48 h</span> — objectif <span class=\"kw-chiffre\">↓ PNN de 25 à 50 %</span></td></tr>\n          <tr><td>Syndrome hépatorénal</td><td><span class=\"kw-def\">Insuffisance rénale fonctionnelle</span> d'un <span class=\"kw-def\">stade</span> avancé, <strong>non corrigée par le remplissage par <span class=\"kw-bio\">albumine</span></strong><br><span class=\"kw-clinique\">Oligurie</span> ; élévation rapide de la <span class=\"kw-bio\">créatininémie</span> ; natriurèse effondrée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Syndrome hépatorénal.</strong> Situation <span class=\"kw-alerte\">grave, parfois irréversible</span>, survenant surtout sur <span class=\"kw-ci\">insuffisance hépatique</span> sévère (<span class=\"kw-bio\">TP</span> &lt;<span class=\"kw-chiffre\"> 50 %</span>) et <span class=\"kw-clinique\">ascite</span> réfractaire. Le diagnostic est retenu en l'absence de <span class=\"kw-alerte\">choc</span>, d'infection, de néphrotoxique et d'anomalie rénale échographique. Seule la <span class=\"kw-ttt\">transplantation hépatique</span> est durablement efficace.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — Hémorragie digestive · 280 — <span class=\"kw-clinique\">Ascite</span> · 348 — <span class=\"kw-def\">Insuffisance rénale aiguë</span> - <span class=\"kw-clinique\">anurie</span></em></p>","frequence":5},{"id":"279-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique d’une cirrhose du foie et de ses principales complications (encéphalopathie hépatique ;  ascite ; hémorragie digestive)","contenu":"<p>La prise en charge associe le <strong>traitement de la cause</strong>, la <strong>prévention et le traitement des complications</strong>, et l'évaluation pronostique en vue d'une éventuelle transplantation.</p>\n      <h4 class=\"obj-h4\">Objectifs selon le <span class=\"kw-def\">stade</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Cirrhose</span> compensée :</strong> maintenir l'état de compensation le plus longtemps possible</li>\n        <li><strong><span class=\"kw-def\">Cirrhose</span> décompensée :</strong> revenir à une situation durable de <span class=\"kw-def\">cirrhose</span> <strong>recompensée</strong></li>\n      </ul>\n      <h4 class=\"obj-h4\">Traiter la cause</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Alcool</span></td><td><strong><span class=\"kw-ttt\">Sevrage</span></strong> complet et définitif ; <span class=\"kw-ttt\">corticothérapie</span> orale si <span class=\"kw-etio\">hépatite</span> alcoolique aiguë avec <span class=\"kw-chiffre\">Maddrey</span> &gt; 32</td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> B</td><td>Analogue (<span class=\"kw-ttt\">entécavir</span>, <span class=\"kw-ttt\">ténofovir</span>) dès ADN <span class=\"kw-etio\">VHB</span> détectable — peut faire régresser la fibrose</td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> C</td><td><span class=\"kw-ttt\">Antiviraux d'action directe</span> en association,<span class=\"kw-chiffre\"> 8 à 12 semaines</span></td></tr>\n          <tr><td><span class=\"kw-etio\">NASH</span> / hémochromatose / CBP</td><td>Contrôle du <span class=\"kw-etio\">surpoids</span>, du <span class=\"kw-etio\">diabète</span>, de la <span class=\"kw-etio\">dyslipidémie</span> ; <span class=\"kw-ttt\">saignées</span> ; <span class=\"kw-ttt\">acide ursodésoxycholique</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\">Prévenir et dépister <span class=\"kw-clinique\">les</span> complications</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td>CHC</td><td><span class=\"kw-imagerie\">Échographie hépatique</span> + <span class=\"kw-bio\">α-fœtoprotéine</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span></td></tr>\n          <tr><td>Encéphalopathie</td><td>PEC des facteurs déclenchants ; <span class=\"kw-ttt\">lactulose</span> ± <span class=\"kw-ttt\">rifaximine</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Ascite</span> et <span class=\"kw-clinique\">œdèmes</span></td><td>Régime hyposodé, <span class=\"kw-ttt\">spironolactone</span> ± <span class=\"kw-ttt\">furosémide</span> ; <span class=\"kw-clinique\">ponction</span> + <span class=\"kw-ttt\">albumine 20 %</span></td></tr>\n          <tr><td>Hémorragie digestive</td><td><span class=\"kw-imagerie\">FOGD de dépistage</span> des <span class=\"kw-clinique\">varices œsophagiennes</span> si <span class=\"kw-chiffre\">plaquettes &lt; 150 G/L</span> ou <span class=\"kw-chiffre\">élasticité hépatique &lt; 20 kPa</span> (<span class=\"kw-bio\">plaquettes</span> + <span class=\"kw-imagerie\">Fibroscan</span> <span class=\"kw-chiffre\">1×/an</span>)<br><span class=\"kw-def\">Prévention primaire</span> et secondaire selon la <span class=\"kw-imagerie\">FOGD</span> : <span class=\"kw-ttt\">β-bloquants non cardiosélectifs</span> (<span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">nadolol</span> ou <span class=\"kw-ttt\">carvédilol</span>) — objectif <span class=\"kw-chiffre\">↓ FC 25 %</span> ou <span class=\"kw-chiffre\">FC &lt; 55 bpm</span> ; l<span class=\"kw-chiffre\">iga</span>ture élastique</td></tr>\n          <tr><td>Vaccinations</td><td><span class=\"kw-ttt\">Anti-pneumococcique</span>, <span class=\"kw-ttt\">antigrippale</span>, <span class=\"kw-ttt\">anti-COVID</span>, <span class=\"kw-ttt\">anti-VHA</span> et <span class=\"kw-ttt\">anti-VHB</span> (en l'absence d'immunité <span class=\"kw-etio\">acquise</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\">Hémorragie digestive aiguë — principes de prise en charge</h4>\n      <table >\n        <thead><tr><th>Mesure</th><th>Molécule(s) / Modalité</th><th>Durée / Cible</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Médicament vaso-actif IV précoce</strong><br>(dès la phase pré-hospitalière)</td><td><span class=\"kw-ttt\">Terlipressine</span>, <span class=\"kw-ttt\">octréotide</span> ou <span class=\"kw-ttt\">somatostatine</span> ; relais par <span class=\"kw-ttt\">β-bloquant non cardiosélectif</span><br><span class=\"kw-ci\">CI terlipressine : coronaropathie, artériopathie oblitérante (AOMI)</span></td><td><span class=\"kw-chiffre\">2 à 5 jours</span> puis relais au long cours</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> systématique</strong> — <span class=\"kw-alerte\">réduit la mortalité</span></td><td><span class=\"kw-ttt\">C3G (céfotaxime)</span> ++ ; alternatives : <span class=\"kw-ttt\">norfloxacine</span>, <span class=\"kw-ttt\">augmentin</span></td><td><span class=\"kw-chiffre\">7 jours</span></td></tr>\n          <tr><td><strong>Transfusion restrictive</strong></td><td>CGR si <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span></td><td>Objectif <span class=\"kw-chiffre\">Hb 7 à 8 g/dL</span></td></tr>\n          <tr><td><strong>Hémostase endoscopique</strong></td><td><span class=\"kw-imagerie\">Ligature élastique</span> des <span class=\"kw-clinique\">varices œsophagiennes</span> ; <span class=\"kw-imagerie\">colle</span> pour <span class=\"kw-clinique\">les</span> varices gastriques</td><td>—</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">TIPS</span> de sauvetage</strong></td><td>Si échec <span class=\"kw-imagerie\">FOGD</span> ou récidive précoce ; sonde de tamponnement (Blackmore / Linton) possible en attente</td><td>Centre spécialisé</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ci\">Éviter la sonde nasogastrique</span></strong> en cas de suspicion de <span class=\"kw-def\">varices œsophagiennes</span> — risque de plaie variqueuse.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-ttt\">TIPS</span> précoce (&lt;<span class=\"kw-chiffre\"> 72 h</span>).</strong> Discuté chez <span class=\"kw-clinique\">les</span> patients <strong><span class=\"kw-chiffre\">Child-Pugh B</span> + saignement actif</strong> ou <strong><span class=\"kw-chiffre\">Child-Pugh C</span></strong> (sauf C14-C15) — améliore le contrôle du saignement et la <span class=\"kw-def\">mortalité</span> ; mis en place dans les <span class=\"kw-chiffre\">72 h</span> suivant la stabilisation. En <strong><span class=\"kw-def\">prévention secondaire</span></strong>, le <span class=\"kw-clinique\">TIPS</span> est indiqué si nouvel épisode de <span class=\"kw-alerte\">rupture</span> de varices sous double prophylaxie (β-bloquants + l<span class=\"kw-chiffre\">iga</span>ture).\n      </div>\n      <h4 class=\"obj-h4\">Scores pronostiques</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span></th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Child-Pugh</span> (<span class=\"kw-def\">score</span> discontinu)</td><td>Moyen mnémotechnique <strong><span class=\"kw-etio\">TABAC</span></strong> : <span class=\"kw-bio\">TP</span>, <span class=\"kw-clinique\">Ascite</span>, <span class=\"kw-bio\">Bilirubine</span>, <span class=\"kw-bio\">Albumine</span>, <span class=\"kw-clinique\">Confusion (encéphalopathie)</span><br>Classe A (5-6) : survie à<span class=\"kw-chiffre\"> 1 an</span> <span class=\"kw-chiffre\">100 %</span> ; classe B (7-9) : <span class=\"kw-chiffre\">80 %</span> ; classe C (10-15) : <span class=\"kw-chiffre\">45 %</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">MELD</span> (<span class=\"kw-def\">score</span> continu)</td><td>Paramètres : <span class=\"kw-bio\">INR</span>, <span class=\"kw-bio\">bilirubine</span>, <span class=\"kw-bio\">créatinine</span> ; varie de 6 à 40<br>Utilisé en France pour l'<strong>attribution des greffons</strong> ; bénéfice de la greffe démontré si <span class=\"kw-chiffre\">&gt; 15-17</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\">Cotation du <span class=\"kw-def\">score</span> de <span class=\"kw-def\">Child-Pugh</span></h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>1 point</th><th>2 points</th><th>3 points</th></tr></thead>\n        <tbody>\n          <tr><td><strong>T</strong> — <span class=\"kw-bio\">TP</span> (%)</td><td><span class=\"kw-chiffre\">&gt; 50</span></td><td><span class=\"kw-chiffre\">40-50</span></td><td><span class=\"kw-chiffre\">&lt; 40</span></td></tr>\n          <tr><td><strong>A</strong> — <span class=\"kw-clinique\">Ascite</span></td><td>Absente</td><td>Modérée, contrôlable</td><td>Abondante</td></tr>\n          <tr><td><strong>B</strong> — <span class=\"kw-bio\">Bilirubine</span> (µmol/L)</td><td><span class=\"kw-chiffre\">&lt; 35</span></td><td><span class=\"kw-chiffre\">35-50</span></td><td><span class=\"kw-chiffre\">&gt; 50</span></td></tr>\n          <tr><td><strong>A</strong> — <span class=\"kw-bio\">Albumine</span> (g/L)</td><td><span class=\"kw-chiffre\">&gt; 35</span></td><td><span class=\"kw-chiffre\">28-35</span></td><td><span class=\"kw-chiffre\">&lt; 28</span></td></tr>\n          <tr><td><strong>C</strong> — <span class=\"kw-clinique\">Confusion</span> (encéphalopathie)</td><td>Absente</td><td><span class=\"kw-clinique\">Confusion</span> ou <span class=\"kw-clinique\">astérixis</span></td><td><span class=\"kw-clinique\">Coma</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Transplantation hépatique.</strong> Elle reste le <span class=\"kw-alerte\">seul traitement radical et définitif</span> de la <span class=\"kw-def\">cirrhose</span> décompensée sans possibilité d'amélioration des fonctions hépatiques.\n      </div>\n      <h4 class=\"obj-h4\">Transplantation hépatique — indications et <span class=\"kw-ci\">contre-indications</span></h4>\n      <table >\n        <thead><tr><th>Indications (complications conduisant à envisager la greffe)</th><th><span class=\"kw-ci\">Contre-indications</span> principales</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Insuffisance hépatique sévère</span> : <span class=\"kw-clinique\">ictère</span> + <span class=\"kw-bio\">TP &lt; 50 %</span> (ou <span class=\"kw-bio\">INR &gt; 1,7</span>)<br><span class=\"kw-clinique\">Ascite réfractaire</span><br><span class=\"kw-alerte\">Infection du liquide d'ascite</span><br>Épisodes répétés ou chroniques d'<span class=\"kw-alerte\">encéphalopathie hépatique</span><br><span class=\"kw-alerte\">Carcinome hépatocellulaire</span><br>Épisodes répétés d'<span class=\"kw-alerte\">hémorragie digestive</span> malgré un traitement adapté</td><td><span class=\"kw-ci\">Âge &gt; 70 ans</span><br><span class=\"kw-ci\">Affection extra-hépatique grave</span>, non traitable, à risque opératoire<br><span class=\"kw-ci\">ATCD récent de cancer</span> (autre que hépatique)<br><span class=\"kw-ci\">Troubles psychologiques ou psychiatriques</span> compromettant le <span class=\"kw-def\">suivi</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 201 — Transplantation d'organe · 250 — Dénutrition</em></p>","frequence":5},{"id":"279-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge de l’encéphalopathie hépatique","contenu":"<p>La prise en charge de l'<span class=\"kw-def\">encéphalopathie hépatique (EH)</span> associe la <span class=\"kw-alerte\">correction du facteur déclenchant</span>, des mesures de protection et un traitement curatif.</p>\n      <h4 class=\"obj-h4\">Correction du facteur déclenchant</h4>\n      <ul>\n        <li>Étape <span class=\"kw-alerte\">indispensable et prioritaire</span> : rechercher et corriger une <span class=\"kw-etio\">constipation</span>, une <span class=\"kw-etio\">infection bactérienne</span>, une <span class=\"kw-etio\">hémorragie digestive</span>, une <span class=\"kw-etio\">insuffisance rénale</span>, une <span class=\"kw-etio\">hyponatrémie profonde</span>, un <span class=\"kw-etio\">régime riche en protéines</span>, une <span class=\"kw-etio\">hépatite alcoolique aiguë</span>, un <span class=\"kw-etio\">shunt porto-systémique</span> spontané ou <span class=\"kw-etio\">acquis</span> (<span class=\"kw-ttt\">TIPS</span>), ou une prise de <span class=\"kw-ci\">médicaments sédatifs</span></li>\n      </ul>\n      <h4 class=\"obj-h4\">Mesures si <span class=\"kw-clinique\">troubles de la conscience sévères</span></h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Sonde nasogastrique</span> + <strong>position demi-assise</strong> — prévenir l'<span class=\"kw-alerte\">inhalation du contenu gastrique</span></li>\n        <li><span class=\"kw-clinique\">Intubation</span> en cas d'<span class=\"kw-clinique\">encombrement</span> et d'<span class=\"kw-alerte\">hypoxémie sévère</span> malgré ces mesures (situation rare)</li>\n      </ul>\n      <h4 class=\"obj-h4\">Traitement curatif</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Lactulose</span> en <span class=\"kw-def\">1ʳᵉ intention</span> ; <span class=\"kw-ttt\">rifaximine</span> (<span class=\"kw-ttt\">antibiotique non absorbable</span>) si échec du <span class=\"kw-ttt\">lactulose</span></li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Mécanisme du <span class=\"kw-ttt\">lactulose</span>.</strong> Il <strong>acidifie le contenu intestinal</strong> : la <span class=\"kw-bio\">baisse du pH</span> ionise l'<span class=\"kw-bio\">ammoniac</span> en <span class=\"kw-bio\">ions ammonium non absorbables et non toxiques</span>, et favorise le passage de l'<span class=\"kw-bio\">ammoniac</span> vers la lumière intestinale.\n      </div>","frequence":1},{"id":"279-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de l’ascite","contenu":"<p>Le traitement de l'<span class=\"kw-clinique\">ascite</span> du cirrhotique repose sur le <strong>régime hyposodé</strong> et <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-ttt\">diurétiques</span></strong> ; le traitement des <span class=\"kw-clinique\">œdèmes</span> est identique, leur <span class=\"kw-clinique\">évolution</span> étant parallèle à celle de l'<span class=\"kw-clinique\">ascite</span>.</p>\n      <h4 class=\"obj-h4\">Mesures de la <span class=\"kw-clinique\">poussée</span> d'<span class=\"kw-clinique\">ascite</span></h4>\n      <ul>\n        <li><strong>Régime hyposodé large</strong> — environ <span class=\"kw-chiffre\">5 g de sel / jour</span> ; préféré à un régime trop restrictif (risque de mauvaise observance et de <span class=\"kw-alerte\">dénutrition</span>)</li>\n        <li><span class=\"kw-ttt\">Spironolactone</span> en 1ʳᵉ intention — <span class=\"kw-chiffre\">75 mg / jour</span>, augmentation possible jusqu'à <span class=\"kw-chiffre\">400 mg / jour</span></li>\n        <li><span class=\"kw-ttt\">Furosémide</span> associé en cas de réponse insuffisante — <span class=\"kw-chiffre\">40 mg / jour</span>, sans dépasser <span class=\"kw-chiffre\">120 mg / jour</span></li>\n        <li><strong><span class=\"kw-ttt\">Ponction</span> évacuatrice</strong> + expansion volémique : <span class=\"kw-chiffre\">1 flacon d'albumine 20 % pour 2 L</span> ponctionnés</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Restriction hydrique.</strong> Elle est <span class=\"kw-ci\">proscrite</span> : elle ne favorise pas le contrôle de l'<span class=\"kw-clinique\">ascite</span> et <span class=\"kw-alerte\">majore le risque d'insuffisance rénale fonctionnelle</span>.\n      </div>\n      <h4 class=\"obj-h4\">Suite de la prise en charge — situation par situation</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Ascite</span> contrôlée</strong></td><td>Diminution <strong>progressive</strong> des <span class=\"kw-ttt\">diurétiques</span> jusqu'à l'arrêt ; reprise seulement si l'<span class=\"kw-clinique\">ascite</span> réapparaît</td></tr>\n          <tr><td><strong>Hyponatrémie</strong> sous <span class=\"kw-ttt\">diurétiques</span> (fréquente)</td><td><span class=\"kw-bio\">Diminuer les diurétiques</span> si <span class=\"kw-chiffre\">natrémie &lt; 125 mmol/L</span> ou mauvaise tolérance clinique</td></tr>\n          <tr><td><strong>Régime hyposodé</strong> au long cours</td><td>À <span class=\"kw-alerte\">maintenir</span> chez tout patient ayant présenté au moins une <span class=\"kw-clinique\">poussée</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Ascite</span> tendue</strong></td><td><span class=\"kw-clinique\">Ponction évacuatrice</span> + expansion volémique par <span class=\"kw-bio\">albumine</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"obj-h4\">Critères d'efficacité du traitement</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Perte de poids</span> ; reprise de la <span class=\"kw-bio\">diurèse</span> et de la <span class=\"kw-bio\">natriurèse</span></li>\n        <li>Diminution du <span class=\"kw-clinique\">périmètre abdominal</span> et de la gêne fonctionnelle ; régression des <span class=\"kw-clinique\">œdèmes</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 280 — <span class=\"kw-clinique\">Ascite</span></em></p>","frequence":1},{"id":"279-12","rang":"B","rubrique":"Prise en charge / Suivi","titre":"Connaître les principes prévention de l’encéphalopathie hépatique","contenu":"<p>Le traitement de l'<span class=\"kw-alerte\">encéphalopathie hépatique</span> est <span class=\"kw-alerte\">essentiellement préventif</span>.</p>\n      <h4 class=\"obj-h4\">Prise en charge des <span class=\"kw-alerte\">facteurs déclenchants</span></h4>\n      <ul>\n        <li>Repérer et corriger <span class=\"kw-clinique\">les</span> facteurs déclenchants : <span class=\"kw-etio\">constipation</span>, <span class=\"kw-etio\">infection</span>, <span class=\"kw-etio\">hémorragie digestive</span>, <span class=\"kw-etio\">hyponatrémie</span></li>\n        <li><span class=\"kw-ci\">Contre-indiquer les médicaments sédatifs</span>, surtout <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">anxiolytiques</span> et les <span class=\"kw-ci\">hypnotiques</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Régime protidique.</strong> Il faut <span class=\"kw-ci\">éviter le régime pauvre en protides</span> : il est <span class=\"kw-alerte\">inefficace</span> sur l'EH et expose au <span class=\"kw-alerte\">risque de dénutrition</span>.\n      </div>\n      <h4 class=\"obj-h4\"><span class=\"kw-def\">Prévention secondaire</span></h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Lactulose</span>, ± <span class=\"kw-ttt\">rifaximine</span> (<span class=\"kw-ttt\">antibiotique non absorbable</span>)</li>\n      </ul>","frequence":0},{"id":"279-13","rang":"B","rubrique":"Prise en charge / Suivi","titre":"Savoir que le patient cirrhotique est à risque de carcinome hépatocellulaire (CHC)","contenu":"<p>Tout patient cirrhotique est à <span class=\"kw-alerte\">risque de carcinome hépatocellulaire (CHC)</span> : l'<span class=\"kw-def\">incidence</span> du CHC sur <span class=\"kw-def\">cirrhose</span> est de <span class=\"kw-chiffre\">1 à 5 % par an</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Règle fondamentale.</strong> Toute image <strong>nodulaire apparaissant sur une <span class=\"kw-def\">cirrhose</span></strong> est un <span class=\"kw-alerte\">CHC jusqu'à preuve du contraire</span>.\n      </div>\n      <h4 class=\"obj-h4\"><span class=\"kw-def\">Dépistage</span> systématique</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Échographie hépatique</span> + dosage de l'<span class=\"kw-bio\">α-fœtoprotéine (AFP)</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span></li>\n        <li><span class=\"kw-def\">Dépistage</span> proposé tant que l'état du patient permet d'envisager un traitement curatif</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège de l'<span class=\"kw-bio\">AFP</span>.</strong> L'<span class=\"kw-bio\">AFP</span> a une <span class=\"kw-alerte\">mauvaise sensibilité</span> : elle est <strong>normale dans <span class=\"kw-chiffre\">30 %</span></strong> des cas. Une <span class=\"kw-bio\">AFP</span> normale n'élimine pas un CHC. Une <span class=\"kw-chiffre\">élévation &gt; 400 ng/mL</span> chez un cirrhotique a une forte valeur d'orientation diagnostique, mais <span class=\"kw-alerte\">ne suffit jamais seule</span> à affirmer le CHC. Son intérêt actuel est surtout <strong>pronostique</strong>.\n      </div>\n      <h4 class=\"obj-h4\">Caractérisation d'un <span class=\"kw-clinique\">nodule</span></h4>\n      <figure class=\"obj-figure\" role=\"group\" aria-label=\"Comportement du carcinome hépatocellulaire en imagerie injectée : au temps artériel, le nodule prend fortement le contraste (wash-in, hyperdensité) car il est vascularisé par l'artère hépatique ; au temps portal, le nodule se lave et devient hypodense par rapport au parenchyme hépatique rehaussé (wash-out).\">\n        <div class=\"cir-washout\">\n          <div class=\"cir-wpanel\">\n            <svg viewBox=\"0 0 200 150\" role=\"img\" aria-hidden=\"true\">\n              <rect x=\"6\" y=\"6\" width=\"188\" height=\"138\" rx=\"14\" fill=\"var(--accent-dash)\" fill-opacity=\"0.45\"/>\n              <rect x=\"18\" y=\"22\" width=\"164\" height=\"106\" rx=\"18\" fill=\"var(--accent-dash)\"/>\n              <circle cx=\"100\" cy=\"75\" r=\"30\" fill=\"var(--spe-hepato)\"/>\n              <text x=\"100\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\">+++</text>\n            </svg>\n            <b>Temps artériel</b>\n            <span><strong>Wash-in</strong> — <span class=\"kw-clinique\">nodule</span> hyperdense (vascularisé par l'artère hépatique)</span>\n          </div>\n          <div class=\"cir-wpanel\">\n            <svg viewBox=\"0 0 200 150\" role=\"img\" aria-hidden=\"true\">\n              <rect x=\"6\" y=\"6\" width=\"188\" height=\"138\" rx=\"14\" fill=\"var(--accent-dash)\" fill-opacity=\"0.45\"/>\n              <rect x=\"18\" y=\"22\" width=\"164\" height=\"106\" rx=\"18\" fill=\"var(--spe-hepato)\" fill-opacity=\"0.5\"/>\n              <circle cx=\"100\" cy=\"75\" r=\"30\" fill=\"var(--ink)\" fill-opacity=\"0.55\"/>\n              <text x=\"100\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"#fff\">−</text>\n            </svg>\n            <b>Temps portal</b>\n            <span><strong>Wash-out</strong> — <span class=\"kw-clinique\">nodule</span> lavé, hypodense <span class=\"kw-bio\">vs</span> parenchyme rehaussé</span>\n          </div>\n        </div>\n        <figcaption>Le couple <strong>wash-in artériel → wash-out portal</strong> sur une <span class=\"kw-def\">cirrhose</span> certaine permet d'affirmer le <span class=\"kw-alerte\">CHC</span> sans <span class=\"kw-bio\">biopsie</span> (nodule <span class=\"kw-chiffre\">&gt; 1 cm</span>, validé en <span class=\"kw-def\">RCP</span>).</figcaption>\n      </figure>\n      <ul>\n        <li><strong>Imagerie en coupe injectée</strong> (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>) : le CHC, vascularisé par l'artère hépatique, montre une <span class=\"kw-radio\">hyperdensité artérielle (wash-in)</span> puis un <span class=\"kw-radio\">lavage au temps portal (wash-out)</span></li>\n        <li><strong><span class=\"kw-bio\">Biopsie</span> non indispensable</strong> si <span class=\"kw-clinique\">nodule</span> <span class=\"kw-chiffre\">&gt; 1 cm</span> avec wash-in et wash-out, développé sur une <strong><span class=\"kw-def\">cirrhose</span> certaine</strong>, avec validation du diagnostic en <span class=\"kw-def\">RCP</span></li>\n        <li>Dans <span class=\"kw-clinique\">les</span> autres cas, la <span class=\"kw-bio\">preuve histologique</span> par <span class=\"kw-bio\">biopsie</span> écho-guidée du <span class=\"kw-clinique\">nodule</span> (couplée à une <span class=\"kw-bio\">biopsie</span> en foie sain) reste indiquée</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie</em></p>","frequence":4}],"astuces":[{"type":"tip","titre":"Mnémo « IHC + HTP » pour décrire toute cirrhose","contenu":"<p>Devant un cirrhotique, structure ta réponse en 2 syndromes :</p>\n<ul>\n  <li><strong><span class=\"kw-bio\">IHC</span></strong> (<span class=\"kw-alerte\">insuffisance hépatocellulaire</span>) :\n    <ul>\n      <li>Cutané : <span class=\"kw-clinique\">angiomes stellaires</span>, <span class=\"kw-clinique\">érythrose palmaire</span>, <span class=\"kw-clinique\">ongles blancs</span>, hippocratisme, <span class=\"kw-clinique\">ictère</span></li>\n      <li>Endocrinien : <span class=\"kw-clinique\">gynécomastie</span>, <span class=\"kw-clinique\">atrophie testiculaire</span>, <span class=\"kw-clinique\">dépilation</span>, <span class=\"kw-clinique\">aménorrhée</span></li>\n      <li>Hémato : tendance <span class=\"kw-alerte\">hémorragique</span>, ↓ <span class=\"kw-bio\">TP</span> / <span class=\"kw-bio\">facteur V</span></li>\n      <li>Neuro : <span class=\"kw-clinique\">astérixis</span>, <span class=\"kw-def\">EH</span></li>\n      <li>Bio : ↓ <span class=\"kw-bio\">albumine</span>, ↓ <span class=\"kw-bio\">TP</span>, ↑ <span class=\"kw-bio\">bilirubine</span>, ↓ <span class=\"kw-bio\">facteur V</span></li>\n    </ul>\n  </li>\n  <li><strong><span class=\"kw-def\">HTP</span></strong> (<span class=\"kw-clinique\">hypertension</span> portale) :\n    <ul>\n      <li><span class=\"kw-clinique\">Splénomégalie</span> + <span class=\"kw-bio\">thrombopénie</span>/hypersplénisme</li>\n      <li><span class=\"kw-clinique\">Circulation collatérale</span> abdominale (<span class=\"kw-clinique\">tête de méduse</span>)</li>\n      <li><span class=\"kw-def\">Ascite</span></li>\n      <li><span class=\"kw-def\">VO</span>, <span class=\"kw-def\">varices gastriques</span>, hémorroïdes</li>\n      <li><span class=\"kw-def\">Gastropathie d'HTP</span></li>\n    </ul>\n  </li>\n</ul>\n<p>+ <strong><span class=\"kw-def\">foie</span> cirrhotique</strong> : <span class=\"kw-clinique\">bord inférieur tranchant</span>, surface bosselée, consistance dure. En QCM, citer ces 3 dimensions = points garantis.</p>"},{"type":"danger","titre":"Piège EDN : 4 complications, 4 réflexes urgents","contenu":"<table class=\"matrix\"><thead><tr><th>Complication</th><th>Réflexe à avoir</th></tr></thead><tbody>\n<tr><td><span class=\"kw-clinique\">Hémorragie digestive</span> (<span class=\"kw-def\">VO</span>)</td><td><strong><span class=\"kw-ttt\">Remplissage</span> prudent (<span class=\"kw-bio\">Hb</span> cible <span class=\"kw-chiffre\">7-8 g</span>/dL)</strong> + <span class=\"kw-ttt\">terlipressine</span> + <strong><span class=\"kw-ttt\">ceftriaxone</span> systématique</strong> + <span class=\"kw-imagerie\">FOGD</span> &lt; <span class=\"kw-chiffre\">12 h</span></td></tr>\n<tr><td><span class=\"kw-def\">EH</span></td><td><strong>Chercher le facteur déclenchant</strong> (infection ++) + <span class=\"kw-ttt\">lactulose</span>, pas de restriction protéique</td></tr>\n<tr><td><span class=\"kw-alerte\">ILA</span></td><td><strong><span class=\"kw-imagerie\">Ponction d'ascite</span> systématique à toute <span class=\"kw-alerte\">hospitalisation</span></strong> ; <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">≥ 250 </span>→ <span class=\"kw-ttt\">C3G</span> + <strong><span class=\"kw-bio\">albumine</span> <span class=\"kw-chiffre\">1,5 g</span>/kg <span class=\"kw-chiffre\">J1</span> + <span class=\"kw-chiffre\">1 g</span>/kg <span class=\"kw-chiffre\">J3</span></strong></td></tr>\n<tr><td><span class=\"kw-def\">SHR</span></td><td><strong>Arrêt <span class=\"kw-ttt\">diurétiques</span> + <span class=\"kw-bio\">albumine</span> <span class=\"kw-chiffre\">1 g</span>/kg/j × <span class=\"kw-chiffre\">2 j</span></strong> (test diagnostique), puis <span class=\"kw-ttt\">terlipressine</span> + <span class=\"kw-bio\">albumine</span> en réa, transplantation</td></tr>\n</tbody></table>\n<p><strong>Piège <span class=\"kw-ttt\">AINS</span>-<span class=\"kw-ttt\">IEC</span>-ARA2-aminosides-iodés</strong> : <span class=\"kw-ci\">à proscrire</span> en aigu chez le cirrhotique décompensé (<span class=\"kw-def\">IRA</span>, <span class=\"kw-def\">SHR</span>).</p>\n<p><strong>Piège BZD/<span class=\"kw-ttt\">opioïdes</span></strong> : précipitent l'<span class=\"kw-def\">EH</span> — éviter, préférer <span class=\"kw-ttt\">paracétamol</span> max <span class=\"kw-chiffre\">2-3 g/j</span>.</p>\n<p><strong>Piège sur-transfusion</strong> dans la <span class=\"kw-alerte\">rupture</span> <span class=\"kw-def\">VO</span> : <span class=\"kw-bio\">Hb</span> &gt; <span class=\"kw-chiffre\">9 g</span>/dL = ↑ <span class=\"kw-def\">HTP</span>, ↑ <span class=\"kw-alerte\">récidive</span> <span class=\"kw-alerte\">hémorragique</span>, ↑ <span class=\"kw-alerte\">mortalité</span>.</p>"},{"type":"warn","titre":"Score de Child-Pugh : le mnémo « BATAE »","contenu":"<p>Pour retenir <span class=\"kw-clinique\">les</span> 5 items du <strong><span class=\"kw-def\">Child-Pugh</span></strong> : <strong>B-A-T-A-E</strong></p>\n<ul>\n  <li><strong>B</strong>ilirubine</li>\n  <li><strong>A</strong>lbumine</li>\n  <li><strong>T</strong>P</li>\n  <li><strong>A</strong>scite</li>\n  <li><strong>E</strong>ncéphalopathie</li>\n</ul>\n<p>Cotation : 1 <span class=\"kw-chiffre\">/ 2 </span><span class=\"kw-chiffre\">/ 3</span> points chacun → total <span class=\"kw-chiffre\">/15</span>.</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Child</span> A</strong> :<span class=\"kw-chiffre\"> 5-6</span> pts (compensée)</li>\n  <li><strong><span class=\"kw-def\">Child</span> B</strong> :<span class=\"kw-chiffre\"> 7-9</span> pts (décompensée modérée)</li>\n  <li><strong><span class=\"kw-def\">Child</span> C</strong> :<span class=\"kw-chiffre\"> 10-15</span> pts (décompensée sévère)</li>\n</ul>\n<p>À ne pas confondre avec le <strong><span class=\"kw-def\">MELD</span></strong> (<span class=\"kw-bio\">bilirubine</span> + <span class=\"kw-bio\">INR</span> + <span class=\"kw-bio\">créatinine</span>) utilisé pour la <strong>priorisation sur liste de transplantation</strong>. <span class=\"kw-def\">MELD</span> <span class=\"kw-chiffre\">≥ 15 </span>→ discuter <span class=\"kw-ttt\">transplantation hépatique</span>.</p>"},{"type":"info","titre":"Astuce PU : le dépistage du CHC ne s'arrête JAMAIS","contenu":"<p>Même après <strong>RVS sous DAA pour <span class=\"kw-etio\">VHC</span></strong> ou <strong><span class=\"kw-ttt\">sevrage alcoolique</span> complet</strong>, le <span class=\"kw-def\">dépistage</span> du <span class=\"kw-def\">CHC</span> se poursuit <strong>à vie</strong> :</p>\n<ul>\n  <li>Le risque diminue mais n'est pas nul (<span class=\"kw-def\">cirrhose</span> constituée)</li>\n  <li><span class=\"kw-ttt\">Échographie hépatique + AFP /<span class=\"kw-chiffre\">6 mois</span></span>, examinateur expérimenté</li>\n  <li><span class=\"kw-def\">Nodule</span> ≥ <span class=\"kw-chiffre\">1 cm</span> → <span class=\"kw-imagerie\">IRM</span>/<span class=\"kw-imagerie\">TDM</span> 4 phases</li>\n  <li>Diagnostic non invasif si <strong>washin artériel + washout portal/tardif</strong> = <span class=\"kw-def\">CHC</span> sans <span class=\"kw-imagerie\">biopsie</span></li>\n</ul>\n<p><strong><span class=\"kw-def\">Critères de</span> Milan</strong> pour la transplantation : 1 <span class=\"kw-radio\">nodule</span> ≤ <span class=\"kw-chiffre\">5 cm</span> OU <span class=\"kw-chiffre\">≤ 3 </span><span class=\"kw-radio\">nodules</span> ≤ <span class=\"kw-chiffre\">3 cm</span>, sans <span class=\"kw-bio\">envahissement</span> vasculaire ni métastase.</p>\n<p><strong>Population à dépister hors <span class=\"kw-def\">cirrhose</span></strong> : porteurs chroniques du <span class=\"kw-etio\">VHB</span> avec ADN élevé, ATCD familiaux, &gt; <span class=\"kw-chiffre\">40 ans</span> (H) / <span class=\"kw-chiffre\">50 ans</span> (F), origine africaine ou asiatique.</p>"},{"type":"tip","titre":"Baveno VII : quand peut-on se passer de FOGD ?","contenu":"<p><span class=\"kw-clinique\">Les</span> recommandations <strong><span class=\"kw-def\">Baveno</span> VII (2022)</strong> permettent d'éviter la <span class=\"kw-imagerie\">FOGD</span> de <span class=\"kw-def\">dépistage</span> des <span class=\"kw-def\">VO</span> chez le cirrhotique compensé si :</p>\n<ul>\n  <li><strong><span class=\"kw-def\">Élastométrie</span> &lt; 20 kPa</strong> ET <strong><span class=\"kw-bio\">plaquettes</span> &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>150</span> G/L</span></strong> → pas de <span class=\"kw-def\">VO</span> cliniquement significatives, <span class=\"kw-imagerie\">FOGD</span> non nécessaire</li>\n  <li>Sinon : <span class=\"kw-imagerie\">FOGD</span> à la découverte, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">1-3 ans</span> selon le résultat</li>\n</ul>\n<p><strong><span class=\"kw-def\">Prévention primaire</span> de la <span class=\"kw-alerte\">rupture</span> <span class=\"kw-def\">VO</span></strong> :</p>\n<ul>\n  <li>Pas de <span class=\"kw-def\">VO</span> ou petites sans signes rouges → pas de traitement</li>\n  <li><span class=\"kw-def\">VO</span> <span class=\"kw-def\">grade</span> I avec signes rouges, ou <span class=\"kw-chiffre\">grade II</span>-III → <strong><span class=\"kw-ttt\">β-bloquant</span> non cardiosélectif</strong> (<span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">carvédilol</span> — objectif FC -<span class=\"kw-chiffre\">25 %</span> ou <span class=\"kw-chiffre\">≤ 55</span>/min)</li>\n  <li><span class=\"kw-def\">CI</span> ou <span class=\"kw-alerte\">intolérance</span> aux <span class=\"kw-ttt\">β-bloquants</span> → <strong>l<span class=\"kw-chiffre\">iga</span>ture élastique itérative</strong></li>\n</ul>\n<p><strong><span class=\"kw-def\">Prévention secondaire</span></strong> (après <span class=\"kw-alerte\">rupture</span>) = combinaison <strong><span class=\"kw-ttt\">β-bloquant</span> + l<span class=\"kw-chiffre\">iga</span>ture</strong> itérative tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">15 jours</span> jusqu'à éradication.</p>"}],"strategie":{"urgence":"<p><strong>Degré</strong></p><ul><li>toute <span class=\"kw-alerte\">décompensation</span> aiguë (HD, <span class=\"kw-clinique\">ascite</span> infectée, EH <span class=\"kw-def\">grade</span> 3-4, <span class=\"kw-alerte\">SHR</span>) = <span class=\"kw-alerte\">urgence vitale</span>, <span class=\"kw-def\">mortalité</span> élevée +++</li></ul><p><strong><span class=\"kw-def\">Surveillance</span> systématique</strong></p><ul><li><span class=\"kw-def\">dépistage</span> <span class=\"kw-def\">CHC</span> (<span class=\"kw-imagerie\">écho hépatique</span> + <span class=\"kw-bio\">α-fœtoprotéine</span>) <span class=\"kw-chiffre\">tous les 6 mois</span></li><li><span class=\"kw-imagerie\">EOGD</span> de <span class=\"kw-def\">dépistage</span> des <span class=\"kw-def\">varices œsophagiennes</span> si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 150 G/L</span> ou <span class=\"kw-bio\">Fibroscan</span> <span class=\"kw-chiffre\">≥ 20 kPa</span>, à répéter <span class=\"kw-chiffre\">1×/an</span></li></ul><p><strong>1er geste devant <span class=\"kw-alerte\">décompensation</span></strong></p><p><span class=\"kw-clinique\">ponction d'ascite exploratrice systématique</span> à chaque <span class=\"kw-clinique\">poussée</span> (l'<span class=\"kw-def\">infection du liquide d'ascite</span> peut être asymptomatique)</p><p><strong>Si <span class=\"kw-alerte\">rupture</span> VO</strong></p><ul><li><span class=\"kw-ttt\">vasoactifs IV</span> (<span class=\"kw-ttt\">terlipressine</span>, <span class=\"kw-ttt\">octréotide</span> ou <span class=\"kw-ttt\">somatostatine</span>) dès la <strong>phase pré-hospitalière</strong> (<span class=\"kw-alerte\">SAMU</span>/domicile)</li><li><span class=\"kw-imagerie\">EOGD</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12h</span> après stabilisation</li></ul><p><strong>Contrôle <span class=\"kw-alerte\">ILA</span></strong></p><p><span class=\"kw-clinique\">2ème ponction exploratrice à 48h</span> ⭐ (objectif : <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">↓ &gt; 25-50%</span>)</p>","hospit":"<p><strong>Ambulatoire :</strong> cirrhose compensée asymptomatique → <span class=\"kw-def\">suivi</span> spécialisé hépato + <span class=\"kw-def\">dépistage</span> CHC <span class=\"kw-chiffre\">/6 mois</span>.<br><strong>Hospit conventionnelle :</strong> toute <strong><span class=\"kw-alerte\">décompensation</span></strong> (apparition d'<span class=\"kw-clinique\">ascite</span>, <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-clinique\">encéphalopathie</span>, <span class=\"kw-clinique\">hémorragie digestive</span>) ; toute <span class=\"kw-def\">infection du liquide d'ascite</span> ; toute <span class=\"kw-clinique\">EH</span> ≥ <span class=\"kw-def\">grade</span> 2.<br><strong>USC / <span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">hémorragie digestive avec instabilité hémodynamique</span> ou <span class=\"kw-alerte\">choc hémorragique</span> ; <span class=\"kw-alerte\">EH grade 3-4</span> (somnolence marquée, <span class=\"kw-alerte\">coma</span>) avec <span class=\"kw-alerte\">encombrement</span> ou <span class=\"kw-alerte\">hypoxémie sévère</span> (<span class=\"kw-ttt\">intubation</span>) ; <span class=\"kw-alerte\">syndrome hépato-rénal</span> ; <span class=\"kw-alerte\">ACLF</span> avec <span class=\"kw-alerte\">défaillance</span> d'organe.<br><strong>Centre spécialisé :</strong> pose de <span class=\"kw-ttt\">TIPS</span> (échec double prophylaxie VO ; <span class=\"kw-clinique\">ascite</span> réfractaire) ; <span class=\"kw-ttt\">transplantation hépatique</span> (seul traitement définitif).</p>","redflags":"<ul><li>Toute <span class=\"kw-alerte\">hématémèse</span>, <span class=\"kw-alerte\">méléna</span> ou <span class=\"kw-alerte\">hématochézie</span> chez un cirrhotique = <span class=\"kw-alerte\">rupture</span> VO jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Tachycardie</span> = signe précoce de <span class=\"kw-alerte\">choc</span> (faussement absente si <span class=\"kw-ci\">β-bloquant</span>) ; <span class=\"kw-alerte\">hypotension</span> + <span class=\"kw-alerte\">pâleur cutanéo-muqueuse</span></li><li><span class=\"kw-alerte\">Astérixis (flapping)</span> = orientation EH +++ (signe majeur même si non spécifique)</li><li><span class=\"kw-alerte\">Trouble de la conscience</span> / <span class=\"kw-alerte\">désorientation</span> / <span class=\"kw-alerte\">coma</span> (EH <span class=\"kw-def\">grade</span> 3-4) ; <span class=\"kw-alerte\">Babinski bilatéral</span> au <span class=\"kw-def\">stade</span> de <span class=\"kw-alerte\">coma</span></li><li><span class=\"kw-alerte\">Ictère récent</span> <span class=\"kw-chiffre\">&lt; 3 mois</span> + <span class=\"kw-alerte\">fièvre</span> + douleur HCD → suspicion d'<span class=\"kw-def\">hépatite alcoolique aiguë</span> (mime <span class=\"kw-clinique\">angiocholite</span>)</li><li><span class=\"kw-alerte\">Oligurie</span> + <span class=\"kw-bio\">↗ rapide créatininémie</span> (pas de seuil) + <span class=\"kw-bio\">natriurèse effondrée</span> → suspicion de <span class=\"kw-def\">syndrome hépato-rénal</span></li><li><span class=\"kw-def\">Score</span> de <span class=\"kw-def\">Maddrey</span> <span class=\"kw-chiffre\">&gt; 32</span> (HAA grave) ; <span class=\"kw-def\">Child-Pugh C</span> (<span class=\"kw-chiffre\">10-15</span>) ; <span class=\"kw-def\">MELD</span> <span class=\"kw-chiffre\">&gt; 17</span></li><li><span class=\"kw-bio\">Bilirubine totale</span> <span class=\"kw-chiffre\">&gt; 50 µmol/L</span> + <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 50%</span> ; <span class=\"kw-bio\">facteur V effondré</span> (facteur de gravité <span class=\"kw-bio\">IHC</span>)</li><li>Liquide d'<span class=\"kw-clinique\">ascite</span> <span class=\"kw-alerte\">polymicrobien</span> + <span class=\"kw-imagerie\">pneumopéritoine</span> → suspicion de <span class=\"kw-alerte\">perforation digestive</span></li><li><span class=\"kw-alerte\">Hépatite alcoolique aiguë</span> avec <span class=\"kw-clinique\">encéphalopathie</span> → indication formelle de <span class=\"kw-bio\">PBH</span> + <span class=\"kw-ttt\">corticothérapie</span><span class=\"kw-chiffre\"> 1 mois</span> (quel que soit le <span class=\"kw-chiffre\">Maddrey</span>)</li></ul>","principes":"<p><strong>Stratégie globale :</strong> traiter la <strong>cause</strong> (régression possible de la fibrose), <strong>prévenir/traiter <span class=\"kw-clinique\">les</span> complications</strong>, évaluer la <strong>sévérité</strong> (<span class=\"kw-def\">Child-Pugh</span> / <span class=\"kw-def\">MELD</span>) pour <span class=\"kw-ttt\">transplantation</span> = seul traitement définitif.</p><p><strong>Traitement étiologique</strong></p><ul><li><span class=\"kw-etio\">alcool</span> → <span class=\"kw-ttt\">arrêt complet et définitif</span>, <span class=\"kw-ttt\">corticothérapie orale 1 mois</span> si <span class=\"kw-def\">Maddrey</span> <span class=\"kw-chiffre\">&gt; 32</span></li><li><span class=\"kw-etio\">VHB</span> → <span class=\"kw-ttt\">entécavir</span> ou <span class=\"kw-ttt\">ténofovir</span> (à vie, dès ADN détectable)</li><li><span class=\"kw-etio\">VHC</span> → <span class=\"kw-ttt\">antiviraux directs</span> (<span class=\"kw-ttt\">sofosbuvir</span>, lédipasvir…) <span class=\"kw-chiffre\">8-12 semaines</span></li><li><span class=\"kw-etio\">NASH</span> → contrôle poids/<span class=\"kw-etio\">diabète</span>/dyslipidémie</li><li><span class=\"kw-etio\">hémochromatose</span> → <span class=\"kw-ttt\">saignées</span></li></ul><p><strong>Vaccinations systématiques</strong></p><ul><li><span class=\"kw-ttt\">anti-pneumococcique</span>, <span class=\"kw-ttt\">anti-grippal</span>, <span class=\"kw-ttt\">anti-COVID</span>, <span class=\"kw-ttt\">anti-VHA</span> et <span class=\"kw-ttt\">anti-VHB</span> (si non immunisé)</li></ul><p><strong><span class=\"kw-def\">Dépistage</span> CHC</strong></p><ul><li><span class=\"kw-imagerie\">échographie hépatique</span> + <span class=\"kw-bio\">α-fœtoprotéine</span> <span class=\"kw-chiffre\">tous les 6 mois</span></li></ul><p><strong><span class=\"kw-clinique\">Ascite</span> <span class=\"q\">(<span class=\"kw-clinique\">poussée</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">régime hyposodé</span> <span class=\"kw-chiffre\">5 g/j</span> (80-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>120</span> mmol</span>)</li><li><span class=\"kw-ttt\">spironolactone</span> <span class=\"kw-chiffre\">75 → 400 mg/j</span> ± <span class=\"kw-ttt\">furosémide</span> <span class=\"kw-chiffre\">40 → 120 mg/j</span></li><li><span class=\"kw-ttt\">ponction évacuatrice</span> + <span class=\"kw-ttt\">albumine 20%</span> (<span class=\"kw-chiffre\">1 flacon pour 2 L</span> ponctionnés, au-delà du 5ème L)</li><li><span class=\"kw-ci\">restriction hydrique proscrite</span></li></ul><p><strong>Hémorragie digestive <span class=\"q\">(<span class=\"kw-alerte\">rupture</span> VO)</span></strong></p><ul><li><span class=\"kw-ttt\">vasoactifs IV</span> (<span class=\"kw-ttt\">terlipressine</span> / <span class=\"kw-ttt\">octréotide</span> / <span class=\"kw-ttt\">somatostatine</span>) <span class=\"kw-chiffre\">2-5 j</span>, puis relais <span class=\"kw-ttt\">β-bloquant</span></li><li><span class=\"kw-ttt\">ATB prophylactique</span> (<span class=\"kw-ttt\">céfotaxime</span> ou norfloxacine, <span class=\"kw-chiffre\">7 j</span>)</li><li><span class=\"kw-ttt\">CGR</span> cible <span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">7-8 g/dL</span></li><li><span class=\"kw-ttt\">EOGD</span> avec <span class=\"kw-ttt\">ligature élastique</span> (VO) ou <span class=\"kw-ttt\">sclérose à la colle</span> (VG)</li><li><span class=\"kw-ci\">éviter la SNG</span></li><li>échec → <span class=\"kw-ttt\">sonde de Blackmore/Linton</span> puis <span class=\"kw-ttt\">TIPS</span></li></ul><p><strong><span class=\"kw-clinique\">Encéphalopathie hépatique</span></strong></p><ul><li><strong>correction du facteur déclenchant</strong> (<span class=\"kw-clinique\">constipation</span>, sédatifs, infection, HD, IRA, hyponatrémie, HAA)</li><li><span class=\"kw-ttt\">lactulose</span>, puis <span class=\"kw-ttt\">rifaximine</span> si échec</li><li>si <span class=\"kw-def\">grade</span> 3-4 → <span class=\"kw-ttt\">SNG</span> + <span class=\"kw-ttt\">position demi-assise</span>, <span class=\"kw-ttt\">intubation</span> si encombrement/hypoxémie</li><li><span class=\"kw-ci\">CI sédatifs</span> (anxiolytiques, hypnotiques)</li><li><span class=\"kw-ci\">pas de régime pauvre en protides</span> (risque de dénutrition)</li></ul><p><strong><span class=\"kw-alerte\">Infection du liquide d'<span class=\"kw-clinique\">ascite</span></span></strong></p><ul><li><span class=\"kw-ttt\">céfotaxime</span> IV (1ʳᵉ intention communautaire) ou <span class=\"kw-ttt\">augmentin</span>/<span class=\"kw-ttt\">ofloxacine</span> (2ᵉ intention)</li><li>nosocomial → <span class=\"kw-ttt\">pipéracilline-tazobactam</span></li><li>durée <span class=\"kw-chiffre\">5-7 j</span></li><li><span class=\"kw-ttt\">albumine 20%</span> à <span class=\"kw-chiffre\">J1 + J3</span></li><li><span class=\"kw-ci\">arrêt des diurétiques</span></li><li><span class=\"kw-clinique\">ponction de contrôle à 48h</span></li></ul><p><strong><span class=\"kw-alerte\">Syndrome hépato-rénal</span></strong></p><ul><li><span class=\"kw-ci\">arrêt des diurétiques et des néphrotoxiques</span></li><li><span class=\"kw-ttt\">albumine</span> <span class=\"kw-chiffre\">1 g/kg/j</span> (surtout si <span class=\"kw-bio\">albuminémie</span> <span class=\"kw-chiffre\">&lt; 20 g/L</span>)</li><li><span class=\"kw-ttt\">vasoconstricteur</span> (<span class=\"kw-ttt\">terlipressine</span> ou <span class=\"kw-ttt\">noradrénaline</span>)</li><li><span class=\"kw-ttt\">transplantation hépatique</span> = seul traitement durablement efficace</li></ul><p><strong>Prophylaxie VO</strong></p><ul><li>primaire <span class=\"kw-def\">grade</span> 2-3 → <span class=\"kw-ttt\">β-bloquant non cardiosélectif</span> (<span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">nadolol</span>, <span class=\"kw-ttt\">carvédilol</span> ; objectif <span class=\"kw-bio\">FC</span> <span class=\"kw-chiffre\">&lt; 55 bpm</span> ou <span class=\"kw-chiffre\">-25%</span>) <strong>ou</strong> <span class=\"kw-ttt\">ligature élastique</span></li><li>secondaire (post-hémorragie) → <span class=\"kw-ttt\">β-bloquant</span> + <span class=\"kw-ttt\">ligatures itératives</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-3 semaines</span> jusqu'à éradication</li></ul><p><strong>Transplantation hépatique</strong></p><ul><li>indiquée si : <span class=\"kw-bio\">IHC</span> sévère (<span class=\"kw-clinique\">ictère</span> + <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 50%</span>), <span class=\"kw-clinique\">ascite</span> réfractaire, <span class=\"kw-alerte\">ILA</span>, EH chronique/répétée, CHC, hémorragies digestives répétées. <span class=\"kw-ci\">CI</span> : âge <span class=\"kw-chiffre\">&gt; 70 ans</span>, affection extra-hépatique grave, cancer récent, trouble psychiatrique compromettant le <span class=\"kw-def\">suivi</span></li></ul>","suivi":"<p><strong>Aigu (<span class=\"kw-alerte\">ILA</span>) :</strong> <span class=\"kw-clinique\">ponction de contrôle à 48h</span> → objectif <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">↓ &gt; 25-50%</span> ; guérison affirmée si <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&lt; 250 /mm³</span>.<br><strong><span class=\"kw-ttt\">Diurétiques</span> au long cours :</strong> <span class=\"kw-bio\">ionogramme</span> + <span class=\"kw-bio\">créatininémie</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-4 semaines</span> ; diminuer si <span class=\"kw-bio\">natrémie</span> <span class=\"kw-chiffre\">&lt; 125 mmol/L</span> ou mauvaise tolérance ; objectif = dose minimale efficace.<br><strong>Post-<span class=\"kw-clinique\">poussée</span> d'<span class=\"kw-clinique\">ascite</span> :</strong> <span class=\"kw-ttt\">régime hyposodé</span> maintenu à vie ; <span class=\"kw-ci\">restriction hydrique proscrite</span> ; <span class=\"kw-ci\">pas de régime pauvre en protides</span>.<br><strong>Prévention 2ndaire VO :</strong> <span class=\"kw-imagerie\">EOGD de contrôle</span> tous les <span class=\"kw-chiffre\">6 mois à 1 an</span> (les VO se reconstituent) ; <span class=\"kw-ttt\">β-bloquant</span> + <span class=\"kw-ttt\">ligatures</span> à vie.<br><strong><span class=\"kw-def\">Dépistage</span> CHC :</strong> <span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-bio\">α-fœtoprotéine</span> tous les <span class=\"kw-chiffre\">6 mois</span> à vie.<br><strong>Critères d'efficacité du traitement de l'ascite :</strong> <span class=\"kw-clinique\">perte de poids</span>, <span class=\"kw-clinique\">diurèse</span>, <span class=\"kw-bio\">natriurèse</span>, <span class=\"kw-clinique\">↓ périmètre abdominal</span>, régression des <span class=\"kw-clinique\">œdèmes</span>.<br><strong><span class=\"kw-def\">Surveillance</span> VO de dépistage :</strong> <span class=\"kw-imagerie\">EOGD</span> si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 150 G/L</span> ou <span class=\"kw-bio\">Fibroscan</span> <span class=\"kw-chiffre\">≥ 20 kPa</span>, renouvelée <span class=\"kw-chiffre\">1×/an</span>.</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/54.%20D%C3%A9compensation%20de%20cirrhose.pdf","label":"CeMIR — 54. décompensation de cirrhose"},{"href":"https://www.fmcgastro.org/postu-main/postu-2013-paris/textes-postu-2013-paris/endoscopie-et-hypertension-portale/","label":"Endoscopie et hypertension portale"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient cirrhotique en décompensation aiguë — 4 grands tableaux à reconnaître","detail":"<h4>CAT — <span class=\"kw-alerte\">décompensation</span> aiguë du cirrhotique — Orientation selon la complication dominante</h4>","branches":[{"to":"q-tableau","label":"Quel tableau domine ?","color":"amber"}]},{"id":"q-tableau","kind":"decision","label":"Quelle complication dominante ? — HD · Ascite · EH · SHR","branches":[{"to":"t-hd","label":"Hématémèse · méléna · hématochézie","color":"red"},{"to":"q-pnn","label":"Ascite · distension · matité","color":"amber"},{"to":"t-eh","label":"Astérixis · confusion · coma","color":"red"},{"to":"t-shr","label":"Oligurie · ↗ créatinine rapide","color":"red"}]},{"id":"t-hd","kind":"terminal","label":"Hémorragie digestive (rupture VO ++)","color":"red","detail":"<h4>Conduite immédiate</h4><ul><li><span class=\"kw-ttt\">Vasoactifs IV</span> (<span class=\"kw-ttt\">terlipressine</span> / <span class=\"kw-ttt\">octréotide</span> / <span class=\"kw-ttt\">somatostatine</span>) dès la <strong>phase pré-hospitalière</strong> (domicile, <span class=\"kw-alerte\">SAMU</span>)</li><li><span class=\"kw-ttt\">CGR</span> cible <span class=\"kw-bio\">Hb</span> <span class=\"kw-chiffre\">7-8 g/dL</span> ; ne pas surtransfuser (risque de récidive)</li><li><span class=\"kw-ttt\">ATB prophylactique</span> systématique (<span class=\"kw-ttt\">céfotaxime</span> 1ʳᵉ intention, ou <span class=\"kw-ttt\">norfloxacine</span> / <span class=\"kw-ttt\">augmentin</span>) — réduit la <span class=\"kw-def\">mortalité</span></li><li><span class=\"kw-ttt\">EOGD</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12h</span> après stabilisation : <span class=\"kw-ttt\">ligature élastique</span> (VO) ou <span class=\"kw-ttt\">sclérose à la colle</span> (VG)</li><li><span class=\"kw-ci\">Éviter la SNG</span> si suspicion de VO</li><li><span class=\"kw-ttt\">Lactulose</span> à fortes doses en prévention de l'<span class=\"kw-clinique\">EH</span> (débarrasser le tube digestif du sang)</li></ul><h4>Échec endoscopique / récidive</h4><ul><li><span class=\"kw-ttt\">Sonde de tamponnement</span> (<span class=\"kw-ttt\">Blackmore</span> œsophagien ou <span class=\"kw-ttt\">Linton</span> gastrique) en attente du <span class=\"kw-ttt\">TIPS</span></li><li><span class=\"kw-ttt\">TIPS</span> en <span class=\"kw-alerte\">urgence</span> en centre spécialisé ; <span class=\"kw-ttt\">TIPS précoce</span> (<span class=\"kw-chiffre\">&lt; 72h</span> post-stabilisation) si <span class=\"kw-def\">Child-Pugh B</span> + saignement actif endoscopique ou <span class=\"kw-def\">Child-Pugh C</span> (pas d'intérêt si <span class=\"kw-def\">Child C14/C15</span>)</li></ul><h4>Durée vasoactifs</h4><ul><li><span class=\"kw-chiffre\">2 à 5 jours</span>, puis relais par <span class=\"kw-ttt\">β-bloquant non cardiosélectif</span> au long cours</li></ul><h4><span class=\"kw-def\">Mortalité</span></h4><ul><li><span class=\"kw-alerte\">10%</span> par épisode</li></ul>"},{"id":"q-pnn","kind":"decision","label":"PNN > 250/mm³ à la ponction exploratrice ? — Ponction systématique à chaque poussée","branches":[{"to":"t-ila","label":"PNN > 250 → infection","color":"red"},{"to":"t-ascite","label":"PNN ≤ 250 → ascite simple","color":"amber"}]},{"id":"t-ila","kind":"terminal","label":"Infection du liquide d'ascite (ILA)","color":"red","detail":"<h4>Diagnostic</h4><ul><li><span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 250 /mm³</span> dans l'<span class=\"kw-clinique\">ascite</span> ⭐ (suffit au diagnostic même si culture négative)</li><li>Examen direct positif dans <span class=\"kw-chiffre\">40%</span> ; asciculture (flacons à <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-chiffre\">&gt; 10 mL</span>)</li><li>Monomicrobien (entérobactéries <span class=\"kw-chiffre\">60%</span>) le plus souvent ; <span class=\"kw-alerte\">polymicrobien</span> → rechercher <span class=\"kw-alerte\">perforation digestive</span> + <span class=\"kw-imagerie\">pneumopéritoine</span></li></ul><h4>Traitement</h4><ul><li>Communautaire : <span class=\"kw-ttt\">céfotaxime</span> IV 1ʳᵉ intention ; alternatives : <span class=\"kw-ttt\">augmentin</span> ou <span class=\"kw-ttt\">ofloxacine</span></li><li>Nosocomiale : <span class=\"kw-ttt\">pipéracilline-tazobactam</span></li><li>Durée : <span class=\"kw-chiffre\">5 à 7 jours</span></li><li><span class=\"kw-ttt\">Albumine 20%</span> à <span class=\"kw-chiffre\">J1</span> et <span class=\"kw-chiffre\">J3</span> (améliore survie, diminue risque de <span class=\"kw-alerte\">SHR</span>)</li><li><span class=\"kw-ci\">Arrêt des diurétiques</span></li></ul><h4>Vérification</h4><ul><li><span class=\"kw-clinique\">2ème ponction exploratrice à 48h</span> ⭐ : objectif <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">↓ &gt; 25-50%</span> ; guérison si <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&lt; 250 /mm³</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">ECBU</span>, <span class=\"kw-imagerie\">RXT</span> (rechercher <span class=\"kw-clinique\">porte d'entrée</span> : pneumopathie, urinaire, septicémie)</li></ul><h4>Prévention 2aire</h4><ul><li><span class=\"kw-ttt\">Norfloxacine</span> demi-dose au long cours après 1er épisode</li></ul>"},{"id":"t-ascite","kind":"terminal","label":"Poussée d'ascite (sans infection)","color":"amber","detail":"<h4>Régime</h4><ul><li><span class=\"kw-ttt\">Régime hyposodé large</span> <span class=\"kw-chiffre\">5 g/j</span> de sel (<span class=\"kw-chiffre\">80-120 mmol</span>) — pas plus restrictif (risque de mauvaise observance)</li><li><span class=\"kw-ci\">Restriction hydrique proscrite</span> (majore le risque d'IRA fonctionnelle)</li></ul><h4><span class=\"kw-ttt\">Diurétiques</span></h4><ul><li><span class=\"kw-ttt\">Spironolactone</span> 1ʳᵉ intention <span class=\"kw-chiffre\">75 mg/j</span>, augmentation jusqu'à <span class=\"kw-chiffre\">400 mg/j</span></li><li><span class=\"kw-ttt\">Furosémide</span> en relais si insuffisant <span class=\"kw-chiffre\">40 → 120 mg/j</span></li><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-bio\">iono</span> + <span class=\"kw-bio\">créatininémie</span> toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-4 semaines</span></li></ul><h4><span class=\"kw-clinique\">Ascite</span> tendue</h4><ul><li><span class=\"kw-ttt\">Ponction évacuatrice</span> + <span class=\"kw-ttt\">albumine 20%</span> : <span class=\"kw-chiffre\">1 flacon pour 2 L</span> évacués (au-delà du 5ème L)</li><li>Évacuation complète possible en 1 séance</li></ul><h4>Efficacité</h4><ul><li><span class=\"kw-clinique\">Perte de poids</span>, <span class=\"kw-clinique\">↑ diurèse</span>, <span class=\"kw-bio\">natriurèse</span>, <span class=\"kw-clinique\">↓ périmètre abdominal</span>, régression des <span class=\"kw-clinique\">œdèmes</span></li></ul><h4><span class=\"kw-clinique\">Ascite</span> réfractaire</h4><ul><li><span class=\"kw-ttt\">Ponctions itératives + albumine</span> · <span class=\"kw-ttt\">TIPS</span> (contrôle dans <span class=\"kw-chiffre\">70%</span>, améliore survie) · <span class=\"kw-ttt\">Transplantation hépatique</span> si <span class=\"kw-clinique\">TIPS</span> inenvisageable</li></ul>"},{"id":"t-eh","kind":"terminal","label":"Encéphalopathie hépatique","color":"red","detail":"<h4>Facteurs déclenchants à rechercher</h4><ul><li><span class=\"kw-etio\">Constipation</span>, régime riche en protéines</li><li><span class=\"kw-etio\">Médicaments sédatifs</span> (<span class=\"kw-ci\">anxiolytiques</span>, <span class=\"kw-ci\">hypnotiques</span>)</li><li><span class=\"kw-etio\">Infections bactériennes</span> (notamment <span class=\"kw-alerte\">ILA</span>), <span class=\"kw-etio\">hémorragies digestives</span></li><li><span class=\"kw-etio\">Insuffisance rénale</span>, <span class=\"kw-etio\">hyponatrémie profonde</span></li><li><span class=\"kw-etio\">Hépatite alcoolique aiguë</span>, <span class=\"kw-etio\">shunt porto-systémique</span> (spontané ou <span class=\"kw-clinique\">TIPS</span>)</li></ul><h4>Diagnostic</h4><ul><li><span class=\"kw-bio\">Hyperammonémie</span> nécessaire au diagnostic</li><li><span class=\"kw-clinique\">Grade 1</span> : inversion cycle nycthéméral, lenteur ; <span class=\"kw-clinique\">Grade 2</span> : <span class=\"kw-alerte\">astérixis +++</span>, désorientation T° ; <span class=\"kw-clinique\">Grade 3</span> : somnolence marquée, désorientation TS ; <span class=\"kw-clinique\">Grade 4</span> : <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">Babinski bilatéral</span></li></ul><h4>Traitement curatif</h4><ul><li><strong>Correction du facteur déclenchant</strong> ++</li><li><span class=\"kw-ttt\">Lactulose</span> per os (acidifie le <span class=\"kw-bio\">pH</span> intestinal, ionise l'ammoniac)</li><li><span class=\"kw-ttt\">Rifaximine</span> (ATB non absorbable) si échec du <span class=\"kw-ttt\">lactulose</span></li><li><span class=\"kw-def\">Grade</span> 3-4 : <span class=\"kw-ttt\">SNG</span> + <span class=\"kw-ttt\">position demi-assise</span> (prévenir l'inhalation) ; <span class=\"kw-ttt\">intubation</span> si encombrement + hypoxémie sévère</li></ul><h4>Prévention</h4><ul><li>Essentielle ! Prise en charge des facteurs déclenchants</li><li><span class=\"kw-ci\">CI sédatifs</span> (anxiolytiques, hypnotiques)</li><li><span class=\"kw-ci\">Pas de régime pauvre en protides</span> (risque de dénutrition)</li><li>Prévention 2aire : <span class=\"kw-ttt\">lactulose</span> ± <span class=\"kw-ttt\">rifaximine</span></li></ul>"},{"id":"t-shr","kind":"terminal","label":"Syndrome hépato-rénal","color":"red","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Insuffisance rénale fonctionnelle</span> du cirrhotique <strong>non corrigée par le remplissage par <span class=\"kw-ttt\">albumine</span></strong> ⭐</li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-def\">IHC sévère</span> (<span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">&lt; 50%</span>) + <span class=\"kw-def\">ascite réfractaire</span></li></ul><h4>Présentation</h4><ul><li><span class=\"kw-clinique\">Oligurie</span></li><li><span class=\"kw-bio\">↗ rapide créatininémie</span> et <span class=\"kw-bio\">urée</span> (pas de seuil — alerte dès <span class=\"kw-bio\">↗ modérée</span>)</li><li><span class=\"kw-bio\">Natriurèse effondrée</span> (IRA fonctionnelle)</li></ul><h4>Diagnostic d'élimination</h4><ul><li>Pas de <span class=\"kw-clinique\">choc</span> ni d'<span class=\"kw-clinique\">infection</span> nécessitant drogues vasoactives</li><li>Pas de <span class=\"kw-clinique\">néphrotoxiques</span></li><li>Pas d'anomalie rénale à l'<span class=\"kw-imagerie\">échographie</span></li></ul><h4>CAT</h4><ul><li><strong>Étape 1</strong> : <span class=\"kw-ttt\">remplissage</span> + <span class=\"kw-ci\">arrêt des néphrotoxiques</span></li><li><strong>Étape 2</strong> : si pas d'amélioration (surtout si <span class=\"kw-bio\">albuminémie</span> <span class=\"kw-chiffre\">&lt; 20 g/L</span>) → <span class=\"kw-ttt\">albumine</span> <span class=\"kw-chiffre\">1 g/kg/j</span></li><li><strong>Étape 3</strong> : diagnostic de <span class=\"kw-alerte\">SHR</span> retenu → <span class=\"kw-ttt\">vasoconstricteur</span> (<span class=\"kw-ttt\">terlipressine</span>/<span class=\"kw-ttt\">glypressine</span> ou <span class=\"kw-ttt\">noradrénaline</span>) — effet souvent transitoire</li><li><span class=\"kw-ci\">Interrompre les diurétiques</span> ⚠️ (notamment ceux introduits pour l'<span class=\"kw-clinique\">ascite</span>)</li></ul><h4>Curatif</h4><ul><li><span class=\"kw-ttt\">Transplantation hépatique</span> = seul traitement durablement efficace</li></ul>"}]},"cards":[{"i":"056d8b638989","n":279,"o":"279-1","u":"Définition","t":"Connaître la définition de la cirrhose","q":"Quelle est la physiopathologie générale de la cirrhose et sa réversibilité ?","a":"<p>La cirrhose résulte d'un processus physiopathologique de <strong>destruction/réparation/fibrose</strong>. Toute maladie chronique du foie, si son évolution est prolongée (généralement après <strong>10 à 20 ans</strong>), peut aboutir à une cirrhose par remplacement du tissu hépatique détruit par de la fibrose qui finit par modifier l'architecture du foie.</p><p>Selon les référentiels actuels, la cirrhose constituée est une affection <strong>irréversible</strong>.</p>"},{"i":"322afcc6b123","n":279,"o":"279-1","u":"Définition","t":"Connaître la définition de la cirrhose","q":"Comment définit-on histologiquement la cirrhose ?","a":"<p>La cirrhose est définie par une <strong>fibrose cicatricielle diffuse</strong> du foie, qui présente deux caractères histologiques indissociables :</p><ul><li>Elle est <strong>mutilante</strong> : elle détruit l'architecture lobulaire normale du foie.</li><li>Elle est <strong>annulaire</strong> : elle délimite des nodules de régénération, qui sont des nodules hépatocytaires de structure anormale.</li></ul>"},{"i":"a1001d4eeeee","n":279,"o":"279-1","u":"Définition","t":"Connaître la définition de la cirrhose","q":"Quelle est la différence entre une cirrhose compensée et une cirrhose décompensée ?","a":"<ul><li>Une cirrhose est dite <strong>compensée</strong> lorsqu'elle est à un stade précoce, souvent asymptomatique, bien que des signes cliniques, biologiques ou morphologiques puissent exister.</li><li>Une cirrhose est dite <strong>décompensée</strong> lorsqu'elle s'accompagne de la survenue d'une complication, telle qu'une <strong>hypertension portale</strong>, une <strong>insuffisance hépatocellulaire</strong> ou un <strong>carcinome hépatocellulaire</strong>.</li></ul>"},{"i":"f7492a96d482","n":279,"o":"279-1","u":"Définition","t":"Connaître la définition de la cirrhose","q":"Quels sont les différents types de cirrhose selon la taille des nodules de régénération ?","a":"<ul><li>La <strong>cirrhose micronodulaire</strong> : la majorité des nodules ont une taille ânférieure à <strong>3 mm</strong>.</li><li>La <strong>cirrhose macronodulaire</strong> : les nodules ont une taille supérieure à <strong>3 mm</strong>. Son diagnostic peut être plus difficile.</li><li>Il existe également des <strong>cirrhoses mixtes</strong>, micro et macronodulaires.</li></ul>"},{"i":"405ab176ddd3","n":279,"o":"279-3","u":"Définition","t":"Connaître les stades évolutifs de la cirrhose","q":"Comment définit-on une cirrhose compensée ?","a":"<p>La <strong>cirrhose compensée</strong> est le stade <strong>précoce</strong> de la cirrhose, le plus souvent <strong>asymptomatique</strong>. Des signes cliniques, biologiques ou morphologiques discrets peuvent exister.</p>"},{"i":"628c2f1640f2","n":279,"o":"279-3","u":"Définition","t":"Connaître les stades évolutifs de la cirrhose","q":"Quels sont les deux grands stades évolutifs de la cirrhose ?","a":"<p>La cirrhose évolue en deux grands stades :</p><ul><li>La <strong>cirrhose compensée</strong>.</li><li>La <strong>cirrhose décompensée</strong>.</li></ul>"},{"i":"a834267583ea","n":279,"o":"279-3","u":"Définition","t":"Connaître les stades évolutifs de la cirrhose","q":"Quelles sont les complications majeures définissant la cirrhose décompensée ?","a":"<p>Les complications majeures définissant la cirrhose décompensée sont :</p><ul><li>L'<strong>insuffisance hépatocellulaire</strong> (ascite, ictère, encéphalopathie hépatique, syndrome hépatorénal).</li><li>L'<strong>hypertension portale</strong> (hémorragies digestives par rupture de varices œsophagiennes et/ou gastriques).</li><li>Les <strong>infections bactériennes</strong> (dont l'infection du liquide d'ascite et l'infection à pneumocoque).</li><li>Le <strong>carcinome hépatocellulaire</strong> (CHC).</li></ul>"},{"i":"adb2aadfb7a6","n":279,"o":"279-3","u":"Définition","t":"Connaître les stades évolutifs de la cirrhose","q":"Quelle est la définition de la cirrhose en termes d'évolution et d'étiologie ?","a":"<p>La cirrhose est l'aboutissement sur des décennies d'une inflammation et d'une fibrose hépatiques chroniques, entretenues par un <strong>agent causal</strong> (alcool, NASH, VHB, VHC, hémochromatose, maladies rares).</p>"},{"i":"cc81bf70931f","n":279,"o":"279-3","u":"Définition","t":"Connaître les stades évolutifs de la cirrhose","q":"Comment définit-on le passage à une cirrhose décompensée ?","a":"<p>La cirrhose est dite <strong>décompensée</strong> dès la survenue d'une seule des <strong>complications majeures</strong> (hypertension portale, insuffisance hépatique, infections bactériennes, carcinome hépatocellulaire), qui conditionnent le pronostic et sont associées à une mortalité élevée.</p>"},{"i":"2fb0e45c8a33","n":279,"o":"279-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de cirrhose","q":"Quels sont les principaux signes cliniques d'insuffisance hépatocellulaire pouvant être observés chez un patient cirrhotique ?","a":"<ul><li>L'<strong>ictère conjonctival</strong> ou cutané, qui est un signe tardif et de mauvais pronostic.</li><li>Le <strong>fœtor hepaticus</strong>, une odeur d'haleine caractéristique.</li><li>Les <strong>angiomes stellaires</strong>, surtout s'ils sont <strong>≥ 5</strong> et situés dans le territoire cave supérieur (visage, thorax, membres supérieurs), disparaissant à la vitropression.</li><li>L'<strong>érythrose palmaire et plantaire</strong>.</li><li>L'<strong>hippocratisme digital</strong> et la <strong>leuconychie</strong> (ongles blancs), ou agrandissement de la lunule.</li><li>Des signes d'hypogonadisme : <strong>gynécomastie</strong> et <strong>dépilation</strong> chez l'homme, avec <strong>atrophie des organes génitaux externes</strong> ; <strong>spanioménorrhée</strong> ou <strong>aménorrhée</strong> chez la femme.</li><li>L'<strong>encéphalopathie hépatique</strong>, se manifestant par l'<strong>astérixis</strong>, l'inversion du cycle nycthéméral, des troubles cognitifs mineurs, ou une confusion.</li></ul>"},{"i":"858cfa12d4b2","n":279,"o":"279-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de cirrhose","q":"Quels sont les principaux signes cliniques d'hypertension portale pouvant être observés chez un patient cirrhotique ?","a":"<ul><li>La <strong>splénomégalie</strong>.</li><li>L'<strong>ascite</strong> (se manifestant par une distension abdominale).</li><li>La <strong>circulation veineuse collatérale</strong> épigastrique puis péri-ombilicale, notamment la « tête de méduse ».</li></ul>"},{"i":"e0a3a272c247","n":279,"o":"279-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de cirrhose","q":"Un examen clinique normal permet-il d'éliminer le diagnostic de cirrhose ?","a":"<p>Non, un examen clinique <strong>peut être strictement normal</strong> au stade de cirrhose compensée. Sa normalité n'élimine en rien le diagnostic.</p>"},{"i":"f902d4564d3c","n":279,"o":"279-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de cirrhose","q":"Comment la palpation du foie se manifeste-t-elle chez un patient atteint de cirrhose?","a":"<p>À la palpation, le foie d'un patient cirrhotique, s'il est palpable, est souvent décrit comme <strong>dur</strong>, avec un <strong>bord inférieur tranchant</strong>. Sa taille peut être variable (normale, augmentée ou atrophique).</p>"},{"i":"0475ceaf5afc","n":279,"o":"279-5","u":"Diagnostic positif","t":"Connaître les signes paracliniques (biologiques et échographiques) associés à la cirrhose","q":"Quels sont les signes échographiques indirects d'hypertension portale que l'on peut observer dans le contexte d'une cirrhose ?","a":"<p>Les signes échographiques indirects d'hypertension portale dus à la cirrhose sont :</p><ul><li>Une <strong>augmentation du diamètre de la veine porte</strong>.</li><li>La présence d'<strong>ascite</strong>.</li><li>Une <strong>splénomégalie</strong>.</li><li>La visualisation de <strong>voies de dérivation porto-caves</strong>.</li><li>Au Doppler, un <strong>ralentissement ou une inversion du flux porte</strong> (flux hépatofuge) si l'hypertension portale est sévère.</li></ul>"},{"i":"1e5fd24825d5","n":279,"o":"279-5","u":"Diagnostic positif","t":"Connaître les signes paracliniques (biologiques et échographiques) associés à la cirrhose","q":"Quelles sont les anomalies hématologiques, autres que l'insuffisance hépatocellulaire, pouvant être observées chez un patient atteint de cirrhose ?","a":"<p>Outre l'insuffisance hépatocellulaire, la cirrhose peut entraîner les anomalies hématologiques suivantes :</p><ul><li>Des <strong>cytopénies de séquestration</strong> dues à l'hypersplénisme : <strong>thrombopénie</strong> (la plus fréquente) &gt; leucopénie &gt; anémie.</li><li>Une <strong>anémie d'origine multifactorielle</strong>, qui peut être due à une carence martiale (par saignement digestif chronique), une carence en folates, ou une hémolyse par anomalie corpusculaire acquise (acanthocytose).</li><li>Liés à la consommation d'alcool si c'est l'étiologie : une <strong>macrocytose</strong>.</li></ul>"},{"i":"57b281679291","n":279,"o":"279-5","u":"Diagnostic positif","t":"Connaître les signes paracliniques (biologiques et échographiques) associés à la cirrhose","q":"Quels sont les signes biologiques d'insuffisance hépatocellulaire que l'on peut retrouver dans le diagnostic d'une cirrhose ?","a":"<p>Les signes biologiques d'insuffisance hépatocellulaire, importants pour le diagnostic de cirrhose, incluent :</p><ul><li>Une baisse des facteurs de coagulation : le <strong>facteur VII est le premier touché</strong> (impactant le TP), suivis des facteurs II et X, puis du facteur V (facteur de gravité).</li><li>Une <strong>hypoalbuminémie</strong>.</li><li>Une <strong>hyperbilirubinémie</strong> (conjuguée ou mixte).</li><li>Une <strong>élévation de l'INR</strong>.</li><li>Une <strong>hypofibrinogénémie</strong> dans les formes sévères.</li><li>Un temps de lyse des euglobulines (Von Kaulla) raccourci à <strong>moins de 1 heure</strong>, témoignant d'une hyperfibrinolyse.</li></ul>"},{"i":"cb145b6d8c6a","n":279,"o":"279-5","u":"Diagnostic positif","t":"Connaître les signes paracliniques (biologiques et échographiques) associés à la cirrhose","q":"Quel est un piège classique concernant l'interprétation du bilan martial (ferritine, CST) dans le diagnostic de la cirrhose ?","a":"<p>Un piège classique concernant le bilan martial en cas de cirrhose est que :</p><ul><li>Une <strong>hyperferritinémie</strong> est possible dans toute maladie hépatique active et ne traduit pas forcément une hémochromatose associée.</li><li>Le <strong>coefficient de saturation de la transferrine (CST)</strong> peut être élevé en cirrhose en raison d'une baisse de la synthèse hépatique de la transferrine, sans que cela n'équivaille nécessairement à une surcharge en fer.</li></ul>"},{"i":"e249d98c0ca6","n":279,"o":"279-5","u":"Diagnostic positif","t":"Connaître les signes paracliniques (biologiques et échographiques) associés à la cirrhose","q":"Quels sont les signes échographiques hépatiques directs de la cirrhose ?","a":"<p>Les signes échographiques directs de cirrhose sont :</p><ul><li>Des <strong>contours du foie irréguliers, bosselés</strong>.</li><li>Une <strong>dysmorphie</strong> hépatique, avec fréquemment une atrophie du lobe droit et une hypertrophie du lobe gauche.</li><li>Une <strong>échostructure granitée</strong> du foie.</li></ul>"},{"i":"27ec4196023c","n":279,"o":"279-8","u":"Identifier une urgence","t":"Connaître les quatre principales complications sévères de la cirrhose : hémorragie digestive ; encéphalopathie hépatique ; infection du liquide d’ascite ; syndrome hépato-rénal","q":"Qu'est-ce que le syndrome hépato-rénal et quels sont ses critères diagnostiques majeurs ?","a":"<p>Le syndrome hépato-rénal est une <strong>insuffisance rénale fonctionnelle</strong> d'un stade avancé, <strong>non corrigée par le remplissage par albumine</strong>. Ses repères diagnostiques incluent une <strong>oligurie</strong>, une <strong>élévation rapide de la créatininémie</strong> et une <strong>natriurèse effondrée</strong>. Le diagnostic est retenu en l'absence de <strong>choc, d'infection, de prise de néphrotoxiques et d'anomalie rénale échographique</strong>. Il survient surtout en cas d'insuffisance hépatique sévère (<strong>TP &lt; 50%</strong>) et d'ascite réfractaire. Seule la <strong>transplantation hépatique</strong> est durablement efficace.</p>"},{"i":"a8aeea5ba318","n":279,"o":"279-8","u":"Identifier une urgence","t":"Connaître les quatre principales complications sévères de la cirrhose : hémorragie digestive ; encéphalopathie hépatique ; infection du liquide d’ascite ; syndrome hépato-rénal","q":"Quel est le critère diagnostique de l'infection du liquide d'ascite et quel est le traitement initial recommandé ?","a":"<p>Le diagnostic positif de l'infection du liquide d'ascite (ou péritonite bactérienne spontanée) est établi par la présence de <strong>polynucléaires neutrophiles (PNN) supérieurs à 250/mm³</strong> dans le liquide d'ascite. Le traitement initial recommandé est une <strong>céphalosporine de 3ème génération (C3G)</strong>, comme le <strong>céfotaxime</strong>, associée à de l'<strong>albumine 20% à J1 puis J3</strong>. Une ponction de contrôle est nécessaire à 48h, avec un objectif de réduction des PNN de <strong>25 à 50%</strong>.</p>"},{"i":"a9e785aff035","n":279,"o":"279-8","u":"Identifier une urgence","t":"Connaître les quatre principales complications sévères de la cirrhose : hémorragie digestive ; encéphalopathie hépatique ; infection du liquide d’ascite ; syndrome hépato-rénal","q":"Comment diagnostique-t-on l'encéphalopathie hépatique et quels sont ses principaux signes cliniques ?","a":"<p>Le diagnostic de l'encéphalopathie hépatique repose sur l'accumulation de toxiques non métabolisés, notamment l'<strong>hyperammoniémie</strong>, nécessaire au diagnostic. Les principaux signes cliniques incluent l'<strong>astérixis (flapping tremor)</strong>. L'encéphalopathie est gradée en <strong>plus de 4 grades</strong>, allant du grade 1 (atteinte minimale) au <strong>coma (grade 4)</strong>.</p>"},{"i":"c080983c3469","n":279,"o":"279-8","u":"Identifier une urgence","t":"Connaître les quatre principales complications sévères de la cirrhose : hémorragie digestive ; encéphalopathie hépatique ; infection du liquide d’ascite ; syndrome hépato-rénal","q":"Quelle est l'étiologie principale de l'hémorragie digestive en cas de cirrhose et quels en sont les signes d'alerte ?","a":"<p>L'hémorragie digestive chez le patient cirrhotique est principalement liée à l'<strong>hypertension portale (HTP)</strong>, dont le mécanisme le plus fréquent est la rupture de <strong>varices œsophagiennes</strong>. Les signes d'alerte sont l'<strong>hématémèse</strong> et le <strong>méléna</strong>, auxquels s'ajoute la <strong>tachycardie</strong>, signe le plus précoce (sauf en cas de traitement par bêtabloquants).</p>"}]};